// Episode 2 ("The Year Hitler Started Losing") scenes F01–F24. Each returns the frame's
// SVG content (1920×1080); ids mark the parts the cue sheet animates.
// Requires toon.js, ww2kit.js, geo.js, maps/eu.js, grain.js. Classic script → globalThis.Scenes, WWH.
(function (g) {
  const { Toon, WW, Geo } = g;
  const { C, place, sticker } = Toon;
  const { CAST, P, K } = WW;
  const ink = C.ink;

  // ---------- shared backdrops ----------
  const H = {};
  H.defs = () => `<defs><pattern id="grain" width="256" height="256" patternUnits="userSpaceOnUse"><image href="${g.GRAIN_PNG}" width="256" height="256"/></pattern></defs>`;
  H.grain = () => `<rect width="1920" height="1080" fill="url(#grain)" opacity=".8" pointer-events="none"/>`;
  H.sky = (top = C.sky, bot = "#d8eef7", id = "bg") => `<defs><linearGradient id="${id}-g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${top}"/><stop offset="1" stop-color="${bot}"/></linearGradient></defs><rect width="1920" height="1080" fill="url(#${id}-g)"/>`;
  H.room = (wall = "#d9c7a4", floor = "#b8946a", fy = 820) => `<rect width="1920" height="1080" fill="${wall}"/><rect y="${fy}" width="1920" height="${1080 - fy}" fill="${floor}" stroke="${ink}" stroke-width="5"/>` + Array.from({ length: 9 }, (_, i) => `<path d="M${i * 240} ${fy} L${i * 240 - 120} 1080" stroke="${ink}" stroke-width="3" opacity=".22"/>`).join("");
  H.ground = (y, col = C.grass, dk = C.grassDk) => `<path d="M0 ${y} Q480 ${y - 30} 960 ${y} T1920 ${y} V1080 H0Z" fill="${col}" stroke="${ink}" stroke-width="5"/><path d="M0 ${y + 60} Q600 ${y + 30} 1200 ${y + 70} T1920 ${y + 50} V1080 H0Z" fill="${dk}" opacity=".35"/>`;
  H.clouds = (list = [[260, 170, 1], [1500, 120, 1.3], [980, 230, 0.8]]) => list.map(([x, y, s]) => `<g class="cloud" transform="translate(${x} ${y}) scale(${s})"><path d="M-110 30 C-130 -10 -80 -40 -50 -20 C-40 -60 30 -66 46 -26 C80 -46 130 -16 112 30Z" fill="#fff" stroke="${ink}" stroke-width="5" opacity=".95"/></g>`).join("");
  H.window = (x, y, w, h, sky = "#9fd0ea") => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${sky}" stroke="${ink}" stroke-width="8"/><path d="M${x + w / 2} ${y} V${y + h} M${x} ${y + h / 2} H${x + w}" stroke="${ink}" stroke-width="6"/>`;
  H.table = (x, y, w, col = C.wood) => `<rect x="${x}" y="${y}" width="${w}" height="30" rx="6" fill="${col}" stroke="${ink}" stroke-width="5"/><rect x="${x + 30}" y="${y + 30}" width="22" height="${1080 - y}" fill="${col}" stroke="${ink}" stroke-width="4"/><rect x="${x + w - 52}" y="${y + 30}" width="22" height="${1080 - y}" fill="${col}" stroke="${ink}" stroke-width="4"/>`;
  H.vignette = (o = 0.6) => `<defs><radialGradient id="vig" cx=".5" cy=".5" r=".75"><stop offset=".55" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity="${o}"/></radialGradient></defs><rect width="1920" height="1080" fill="url(#vig)" pointer-events="none"/>`;
  H.date = (x, y, text, id = "") => sticker(x, y, text, { size: 40, rot: -2, bg: ink, id });
  H.label = (x, y, text, size = 34, id = "") => `<text${id ? ` id="${id}"` : ""} x="${x}" y="${y}" text-anchor="middle" class="t-map" font-size="${size}">${text}</text>`;
  H.title = (title, sub) => `<g id="title" opacity="0" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#20222a"/>${Array.from({ length: 12 }, (_, i) => `<path d="M960 540 L${960 + Math.cos(i / 6 * Math.PI) * 1400} ${540 + Math.sin(i / 6 * Math.PI) * 1400} L${960 + Math.cos((i + 0.5) / 6 * Math.PI) * 1400} ${540 + Math.sin((i + 0.5) / 6 * Math.PI) * 1400}Z" fill="#2b2e38"/>`).join("")}<text x="960" y="420" text-anchor="middle" class="t-title" font-size="120" fill="#fffaf0">${title}</text><g transform="translate(960 600) rotate(-2)"><rect x="-760" y="-80" width="1520" height="160" rx="22" fill="${K.red}" stroke="${ink}" stroke-width="10"/><text y="32" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="84" fill="#fffaf0">${sub}</text></g></g>`;
  // Map of a baked view; fills: {countryKey: colour}, ids: country paths get id "c-<key>"
  H.map = (view = "europe", fills = {}, { sea = "#2b4a6b", land = "#d8c49a", ids = [] } = {}) => {
    const v = g.EU[view];
    let s = `<rect width="1920" height="1080" fill="${sea}"/><path d="${v.land}" fill="${land}" stroke="${ink}" stroke-width="4" stroke-linejoin="round"/>`;
    for (const [k, d] of Object.entries(v.c)) {
      const f = fills[k];
      s += `<path${ids.includes(k) ? ` id="c-${k}"` : ""} d="${d}" fill="${f || land}" stroke="${ink}" stroke-width="${f ? 3.5 : 2}" stroke-linejoin="round" opacity="${f ? 1 : 0.9}"/>`;
    }
    return s;
  };
  H.city = (name, view = "europe", { label = name, dx = 0, dy = -22, size = 30, dot = true } = {}) => { const [x, y] = Geo.at(name, view); return (dot ? `<circle cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="9" fill="#fffaf0" stroke="${ink}" stroke-width="4"/>` : "") + `<text x="${(x + dx).toFixed(0)}" y="${(y + dy).toFixed(0)}" text-anchor="middle" class="t-map" font-size="${size}">${label}</text>`; };
  // Fat map arrow along lon/lat points (drawn on by the engine when its id starts with "arr-")
  H.arrow = (pts, view = "europe", { id = "", col = K.red, w = 26 } = {}) => {
    const P2 = pts.map((p) => Geo.project(p, view)), d = Geo.smoothPath(P2);
    const [a, b] = [P2[P2.length - 2], P2[P2.length - 1]], ang = Math.atan2(b[1] - a[1], b[0] - a[0]) * 180 / Math.PI;
    return `<g${id ? ` id="${id}"` : ""}><path d="${d}" stroke="${ink}" stroke-width="${w + 12}" fill="none" stroke-linecap="round"/><path d="${d}" stroke="${col}" stroke-width="${w}" fill="none" stroke-linecap="round"/><path transform="translate(${b[0].toFixed(1)} ${b[1].toFixed(1)}) rotate(${ang.toFixed(1)})" d="M-6 -${w * 1.6} L${w * 2.2} 0 L-6 ${w * 1.6}Z" fill="${col}" stroke="${ink}" stroke-width="6" stroke-linejoin="round"/></g>`;
  };
  H.flagDE = (x, y, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="0" y="-8" width="10" height="220" fill="#555" stroke="${ink}" stroke-width="4"/><rect x="10" y="0" width="150" height="34" fill="#1d1d1d" stroke="${ink}" stroke-width="4"/><rect x="10" y="34" width="150" height="34" fill="${K.red}" stroke="${ink}" stroke-width="4"/></g>`;
  H.cut = (id, inner) => `<g id="${id}" data-layout-allow-overlap="true">${inner}</g>`;
  H.bed = (x, y, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-260" y="-40" width="520" height="70" rx="12" fill="#f4f1ea" stroke="${ink}" stroke-width="6"/><rect x="-280" y="-160" width="24" height="230" rx="6" fill="#9aa3ad" stroke="${ink}" stroke-width="5"/><rect x="256" y="-110" width="24" height="180" rx="6" fill="#9aa3ad" stroke="${ink}" stroke-width="5"/><path d="M-250 -40 C-120 -70 120 -70 250 -40" fill="#c9d6e6" stroke="${ink}" stroke-width="5"/></g>`;

  // ---------- Episode 2 helpers ----------
  // map with extra lon/lat regions (clipped to land) drawn over the country fills
  H.mapX = (view, fills = {}, { sea, land, extra = [], ids = [] } = {}) => {
    const v = g.EU[view], cid = `lc-${view}`;
    return H.map(view, fills, { sea, land, ids }) + `<defs><clipPath id="${cid}"><path d="${v.land}"/></clipPath></defs><g clip-path="url(#${cid})">${extra.map((r) => `<path${r.id ? ` id="${r.id}"` : ""} d="${Geo.poly(r.pts, view)}" fill="${r.fill}" opacity="${r.op ?? 0.92}" stroke="${r.stroke || "none"}" stroke-width="4"/>`).join("")}</g>`;
  };
  H.region = (pts, view, fill, id = "", op = 0.9) => `<path${id ? ` id="${id}"` : ""} d="${Geo.poly(pts, view)}" fill="${fill}" opacity="${op}" stroke="${ink}" stroke-width="3" stroke-linejoin="round"/>`;
  // dark counter panel: a label and the final figure (never ticks up)
  H.counter = (x, y, label, value, id, w = 520) => `<g id="${id}" transform="translate(${x} ${y})"><rect x="${-w / 2}" y="-80" width="${w}" height="160" rx="16" fill="#151820" stroke="#555" stroke-width="5"/><text x="0" y="-28" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="28" fill="#c9c2b0">${label}</text><text x="0" y="50" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="66" fill="#fffaf0">${value}</text></g>`;
  H.pin = (name, view, { label = name, dx = 0, dy = -26, size = 32, col = "#fffaf0", id = "", r = 10 } = {}) => { const [x, y] = Geo.at(name, view); return `<g${id ? ` id="${id}"` : ""}><circle cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="${r}" fill="${col}" stroke="${ink}" stroke-width="4"/>${label ? `<text x="${(x + dx).toFixed(0)}" y="${(y + dy).toFixed(0)}" text-anchor="middle" class="t-map" font-size="${size}">${label}</text>` : ""}</g>`; };
  H.line = (pts, view, { col = ink, w = 8, dash = "", id = "" } = {}) => `<path${id ? ` id="${id}"` : ""} d="${Geo.route(pts, view)}" stroke="${col}" stroke-width="${w}" fill="none" stroke-linecap="round"${dash ? ` stroke-dasharray="${dash}"` : ""}/>`;
  H.tank = (x, y, s = 1, id = "", col = "#5f6650", flip = false) => `<g${id ? ` id="${id}"` : ""} transform="translate(${x} ${y}) scale(${flip ? -s : s} ${s})"><rect x="-230" y="-60" width="460" height="110" rx="40" fill="#3f423a" stroke="${ink}" stroke-width="8"/>${[-170, -85, 0, 85, 170].map((cx) => `<circle cx="${cx}" cy="0" r="34" fill="#2c2e28" stroke="${ink}" stroke-width="5"/>`).join("")}<rect x="-190" y="-150" width="380" height="100" rx="18" fill="${col}" stroke="${ink}" stroke-width="8"/><rect x="-90" y="-230" width="200" height="90" rx="20" fill="${col}" stroke="${ink}" stroke-width="8"/><rect x="-330" y="-205" width="240" height="30" rx="10" fill="#4f554a" stroke="${ink}" stroke-width="6"/></g>`;
  H.plane = (x, y, s, col, flip = false, id = "") => `<g${id ? ` id="${id}"` : ""} transform="translate(${x} ${y}) scale(${flip ? -s : s} ${s})"><path d="M-110 0 C-60 -26 60 -26 110 0 C60 18 -60 18 -110 0Z" fill="${col}" stroke="${ink}" stroke-width="6"/><path d="M-20 -6 L20 -90 L44 -90 L30 -6Z M-20 6 L20 90 L44 90 L30 6Z" fill="${col}" stroke="${ink}" stroke-width="5"/><path d="M-100 -4 L-128 -40 L-112 -40 L-90 -6Z" fill="${col}" stroke="${ink}" stroke-width="4"/></g>`;
  // side-view bomber (twin engine)
  H.bomber = (x, y, s, col = "#7c7a52", flip = false, id = "") => `<g${id ? ` id="${id}"` : ""} transform="translate(${x} ${y}) scale(${flip ? -s : s} ${s})"><path d="M-170 0 C-120 -34 120 -30 170 -6 C130 20 -120 24 -170 0Z" fill="${col}" stroke="${ink}" stroke-width="7"/><path d="M-150 -6 L-180 -70 L-150 -70 L-120 -14Z" fill="${col}" stroke="${ink}" stroke-width="5"/><path d="M-40 6 L40 6 L70 34 L-60 34Z" fill="${col}" stroke="${ink}" stroke-width="5" opacity=".9"/><rect x="-20" y="10" width="60" height="22" rx="10" fill="#555" stroke="${ink}" stroke-width="4"/><path d="M130 -16 Q150 -22 160 -10" stroke="#bfe3f2" stroke-width="10" fill="none"/></g>`;
  H.carrier = (x, y, s = 1, id = "", col = "#7a7e86") => `<g${id ? ` id="${id}"` : ""} transform="translate(${x} ${y}) scale(${s})"><path d="M-300 0 L300 0 L260 60 L-270 60Z" fill="${col}" stroke="${ink}" stroke-width="7"/><rect x="-320" y="-24" width="640" height="26" fill="#9a8a6a" stroke="${ink}" stroke-width="6"/><rect x="120" y="-80" width="60" height="56" fill="${col}" stroke="${ink}" stroke-width="6"/><path d="M-280 -11 H280" stroke="#fffaf0" stroke-width="3" stroke-dasharray="20 14"/></g>`;
  H.bship = (x, y, s = 1, id = "", col = "#8a8e96") => `<g${id ? ` id="${id}"` : ""} transform="translate(${x} ${y}) scale(${s})"><path d="M-260 0 L270 0 L230 56 L-230 56Z" fill="${col}" stroke="${ink}" stroke-width="7"/><rect x="-120" y="-60" width="200" height="60" fill="${col}" stroke="${ink}" stroke-width="6"/><rect x="-40" y="-120" width="60" height="60" fill="${col}" stroke="${ink}" stroke-width="6"/><rect x="-220" y="-30" width="80" height="30" rx="8" fill="${col}" stroke="${ink}" stroke-width="5"/><path d="M-200 -16 L-280 -24" stroke="${ink}" stroke-width="10"/><rect x="120" y="-30" width="80" height="30" rx="8" fill="${col}" stroke="${ink}" stroke-width="5"/><path d="M180 -16 L260 -24" stroke="${ink}" stroke-width="10"/></g>`;
  H.fire = (x, y, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-40 0 C-60 -40 -30 -70 -20 -110 C-10 -80 0 -80 4 -130 C30 -90 50 -60 40 0Z" fill="${C.fire}" stroke="${ink}" stroke-width="5"/><path d="M-20 0 C-30 -30 -10 -50 -4 -74 C6 -50 24 -40 20 0Z" fill="${C.fireLt}"/></g>`;
  H.smoke = (x, y, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})" opacity=".85"><circle cx="0" cy="-60" r="50" fill="#4a4a4f"/><circle cx="40" cy="-130" r="60" fill="#55555a"/><circle cx="-10" cy="-210" r="70" fill="#5f5f64"/></g>`;
  // TURNING POINT card: full-screen slam; earlier boxes already filled, box n slams in
  const TPN = ["MIDWAY", "EL ALAMEIN", "STALINGRAD"];
  H.tp = (n) => `<g id="cut-tp" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#14161c"/>${Array.from({ length: 12 }, (_, i) => `<path d="M960 540 L${960 + Math.cos(i / 6 * Math.PI) * 1400} ${540 + Math.sin(i / 6 * Math.PI) * 1400} L${960 + Math.cos((i + 0.5) / 6 * Math.PI) * 1400} ${540 + Math.sin((i + 0.5) / 6 * Math.PI) * 1400}Z" fill="#1d2029"/>`).join("")}<text x="960" y="250" text-anchor="middle" class="t-title" font-size="96">TURNING POINT ${n} OF 3</text>` +
    [0, 1, 2].map((i) => { const x = 400 + i * 560; return `<rect x="${x - 240}" y="400" width="480" height="300" rx="18" fill="${i < n - 1 ? "#2f6b3a" : "#262a33"}" stroke="#fffaf0" stroke-width="8" stroke-dasharray="${i < n - 1 ? "" : "22 14"}"/><text x="${x}" y="470" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="44" fill="#c9c2b0">${i + 1}</text>${i < n - 1 ? `<text x="${x}" y="600" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="${TPN[i].length > 7 ? 54 : 62}" fill="#fffaf0">${TPN[i]}</text>` : ""}`; }).join("") +
    `<g id="st-tp"><g transform="translate(${400 + (n - 1) * 560} 550) rotate(-3)"><rect x="-250" y="-160" width="500" height="320" rx="18" fill="${K.red}" stroke="#fffaf0" stroke-width="10"/><text y="-60" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="44" fill="#ffd9a0">${n}</text><text y="56" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="${TPN[n - 1].length > 7 ? 58 : 70}" fill="#fffaf0">${TPN[n - 1]}</text></g></g></g>`;
  H.wallmap = (view, fills, inner = "", { x = 160, y = 110, w = 1200, h = 700, sea, extra } = {}) => {
    const sx = w / 1920, sy = h / 1080;
    return `<g transform="translate(${x} ${y})"><rect x="-20" y="-20" width="${w + 40}" height="${h + 40}" fill="#3a2f22" stroke="${ink}" stroke-width="8"/><clipPath id="wm-${view}"><rect width="${w}" height="${h}"/></clipPath><g clip-path="url(#wm-${view})"><g transform="scale(${sx.toFixed(4)} ${sy.toFixed(4)})">${H.mapX(view, fills, { sea, extra })}${inner}</g></g></g>`;
  };
  H.calendar = (x, y, top, big, { id = "", col = K.red, s = 1 } = {}) => `<g${id ? ` id="${id}"` : ""} transform="translate(${x} ${y}) scale(${s})"><rect x="-130" y="-140" width="260" height="280" rx="14" fill="#fffaf0" stroke="${ink}" stroke-width="7"/><rect x="-130" y="-140" width="260" height="70" rx="14" fill="${col}" stroke="${ink}" stroke-width="7"/><text y="-90" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="#fffaf0">${top}</text><text y="50" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="${big.length > 3 ? 64 : 110}" fill="${ink}">${big}</text></g>`;
  H.phone = (x, y, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-60" y="-20" width="120" height="70" rx="12" fill="#2a2a2e" stroke="${ink}" stroke-width="5"/><path d="M-70 -30 C-70 -60 70 -60 70 -30 L50 -20 L-50 -20Z" fill="#2a2a2e" stroke="${ink}" stroke-width="5"/><circle cy="16" r="18" fill="#ddd" stroke="${ink}" stroke-width="4"/></g>`;
  H.doc = (x, y, w, h, lines, { rot = -2, id = "", title = "", size = 30 } = {}) => `<g${id ? ` id="${id}"` : ""} transform="translate(${x} ${y}) rotate(${rot})"><rect x="${-w / 2 + 10}" y="${-h / 2 + 12}" width="${w}" height="${h}" fill="#000" opacity=".35"/><rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" fill="#f6efdc" stroke="${ink}" stroke-width="5"/>${title ? `<text y="${-h / 2 + 70}" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="${size + 6}" fill="${ink}">${title}</text>` : ""}${lines.map((l, i) => typeof l === "string" ? `<text y="${-h / 2 + (title ? 140 : 80) + i * size * 1.6}" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="${size}" fill="#3a3a3a">${l}</text>` : `<path d="M${-w / 2 + 50} ${-h / 2 + (title ? 140 : 80) + i * size * 1.6 - 10} H${w / 2 - 50 - l * 60}" stroke="#bbb" stroke-width="10"/>`).join("")}</g>`;

  const S = {};
  const AX = "#3b3e46", JP = "#7a3a30", SU = "#b04a3a";

  // F01 — Hook: the world, summer 1942; three empty boxes; mud; title
  S["01"] = () => {
    const occSU = [[28, 60], [31, 59.3], [33, 57], [35.5, 55.5], [34.5, 53], [36.5, 51], [38.5, 49.5], [42, 48.7], [44.5, 48.6], [45.5, 46], [44, 43.4], [40, 43.6], [37, 45], [33, 45], [28, 46], [24, 48], [23, 52], [22, 55], [25, 58]];
    const china = [[120, 41.5], [124, 40], [122, 37], [121, 31], [121, 28], [119, 25], [116, 23], [113, 22], [110, 21], [109.5, 23.5], [112, 28], [113, 31], [111, 34], [113, 37], [114, 40], [117, 41.5]];
    const manchuria = [[119, 42], [124, 40], [131, 42.5], [134, 48], [127, 50], [122, 53], [119, 50], [116.5, 47]];
    const egyptW = [[25, 31.7], [29, 30.9], [29, 29], [25, 29]];
    const W = "world";
    const base = H.map(W, {}, { sea: "#2b4a6b" });
    const eu = H.region(occSU, W, AX) + `<g>${["de", "at", "cz", "pl", "fr", "benl", "dk", "no", "it", "yu", "gr", "hu", "ro", "bg", "baltic", "al", "ly", "fi"].filter((k) => g.EU[W].c[k]).map((k) => `<path d="${g.EU[W].c[k]}" fill="${AX}" stroke="${ink}" stroke-width="2"/>`).join("")}</g>` + H.region(egyptW, W, AX);
    const jp = `<g>${["jp", "kr", "tw", "ph", "my", "idn", "mm", "ic", "th"].filter((k) => g.EU[W].c[k]).map((k) => `<path d="${g.EU[W].c[k]}" fill="${JP}" stroke="${ink}" stroke-width="2"/>`).join("")}</g>` + H.region(china, W, JP) + H.region(manchuria, W, JP) +
      [[144.8, 13.4], [166.6, 19.3], [173, 1.4], [159.9, -9.5], [147, -6], [152, -4.3], [138, 7.5], [151.8, 7.4], [171.4, 7.1]].map((p) => { const [x, y] = Geo.project(p, W); return `<circle cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="9" fill="${JP}" stroke="${ink}" stroke-width="3"/>`; }).join("");
    const lbl = (txt, p, size = 40) => { const [x, y] = Geo.project(p, W); return `<text x="${x.toFixed(0)}" y="${y.toFixed(0)}" text-anchor="middle" class="t-map" font-size="${size}">${txt}</text>`; };
    const boxes = [0, 1, 2].map((i) => `<g id="pop-tp${i + 1}" transform="translate(${560 + i * 400} 930)"><rect x="-180" y="-90" width="360" height="180" rx="16" fill="#151820" stroke="#fffaf0" stroke-width="6" stroke-dasharray="20 12"/><text y="-36" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="28" fill="#c9c2b0">TURNING POINT</text><text y="50" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="76" fill="#fffaf0">${i + 1}</text></g>`).join("");
    const mud = `<rect width="1920" height="1080" fill="#8a8f96"/><path d="M0 640 Q960 600 1920 650 V1080 H0Z" fill="#5a4630" stroke="${ink}" stroke-width="6"/>${H.tank(960, 820, 1.6, "", "#5f6650")}<path d="M0 760 Q300 720 620 770 T1300 760 T1920 770 V1080 H0Z" fill="#6b5236" stroke="${ink}" stroke-width="6"/>${Array.from({ length: 9 }, (_, i) => `<ellipse cx="${120 + i * 220}" cy="${850 + (i % 3) * 60}" rx="70" ry="16" fill="#4a3824"/>`).join("")}${sticker(960, 160, "BUT FIRST: MUD", { size: 70, rot: -2, bg: "#6b5236" })}`;
    return H.defs() + base + `<g id="fade-axE">${eu}${lbl("GERMANY &amp; ALLIES", [25, 58], 34)}</g><g id="fade-axJ">${jp}${lbl("JAPAN", [128, 30], 36)}</g>` +
      `<g id="fade-back">${[[[38, 55.5], [30, 54]], [[44, 49], [38, 48]], [[29, 30.8], [22, 32]], [[-177, 28], [170, 30]], [[160, -9], [153, -2]]].map((pts, i) => H.arrow(pts, W, { id: `arr-b${i}`, col: "#2f7a3a", w: 16 })).join("")}</g>` +
      `<g id="pop-axisbox">${sticker(1500, 120, "THE AXIS, SUMMER 1942", { size: 46, rot: 2, bg: ink })}</g>` +
      boxes + H.cut("cut-mud", mud) + H.title("WORLD WAR II", "The Year Hitler Started Losing") + H.grain();
  };

  // F02 — Mud, then ice
  S["02"] = () => {
    const E = "east";
    const map = H.mapX(E, { ussr: SU, de: AX, pl: AX, ro: "#6a6a5a", hu: "#6a6a5a", fi: "#7a8a96", baltic: AX }, { extra: [{ pts: [[22, 56], [28, 59.8], [31, 58.5], [34.5, 56.3], [35.5, 54], [34, 52], [36, 50.5], [36.5, 48], [33.5, 46.4], [30, 46.4], [26, 48], [23.5, 51]], fill: AX }] }) +
      [[[24, 54], [30, 54.6], [35.2, 55.4]], [[24.5, 51], [30.5, 51.5], [34.5, 51.4]], [[27, 48], [31.5, 47.5], [35.5, 47.6]]].map((p, i) => H.arrow(p, E, { id: `arr-g${i}`, col: "#6f7766", w: 22 })).join("") + H.city("Moscow", E) + H.city("Leningrad", E) + H.city("Kiev", E);
    const back = [[[40.5, 57.4], [38.5, 56.9], [36, 56.3]], [[40.5, 54.2], [38.5, 54.4], [36, 54.8]]].map((p, i) => H.arrow(p, E, { id: `arr-s${i}`, col: "#c8352b", w: 26 })).join("");
    const ground = (col, top) => `<path d="M0 700 Q480 680 960 700 T1920 700 V1080 H0Z" fill="${col}" stroke="${ink}" stroke-width="6"/>${top}`;
    const tanks = H.tank(1300, 760, 1.0, "tank1") + H.tank(380, 740, 0.8, "tank2");
    const mudFront = `<path d="M0 770 Q300 740 620 780 T1300 770 T1920 780 V1080 H0Z" fill="#6b5236" stroke="${ink}" stroke-width="6"/>${Array.from({ length: 8 }, (_, i) => `<ellipse cx="${120 + i * 240}" cy="${880 + (i % 3) * 50}" rx="70" ry="16" fill="#4a3824"/>`).join("")}`;
    const iceFront = `<path d="M0 770 Q300 740 620 780 T1300 770 T1920 780 V1080 H0Z" fill="#e8f0f6" stroke="${ink}" stroke-width="6"/>${Array.from({ length: 8 }, (_, i) => `<path d="M${100 + i * 240} ${860 + (i % 3) * 50} l60 -14 l50 20" stroke="#a9c3d6" stroke-width="5" fill="none"/>`).join("")}`;
    const rain = `<g id="storm">${Array.from({ length: 40 }, (_, i) => `<path class="rain" d="M${(i * 53) % 1920} ${(i * 97) % 700} l-14 40" stroke="#c9d8e6" stroke-width="4"/>`).join("")}</g>`;
    const snow = `<g id="fade-snow"><rect width="1920" height="700" fill="#cfd8e0" opacity=".55"/><path d="M0 700 Q480 680 960 700 T1920 700 V780 H0Z" fill="#f4f7fb"/>${H.tank(1300, 760, 1.0, "", "#7d8a86")}${H.tank(380, 740, 0.8, "", "#7d8a86")}${iceFront}${Array.from({ length: 50 }, (_, i) => `<circle class="flake" cx="${(i * 131) % 1920}" cy="${(i * 71) % 900}" r="${4 + (i % 3) * 2}" fill="#fff"/>`).join("")}</g>`;
    const cold = `<rect width="1920" height="1080" fill="#d9e2ea"/><path d="M0 760 Q960 720 1920 760 V1080 H0Z" fill="#f4f7fb" stroke="${ink}" stroke-width="5"/>${[360, 760, 1160, 1560].map((x, i) => place(CAST.soldierDE({ pose: "cross", brows: "sad", mouth: "wobbly", sweat: false }), x, 1000, 1.25, { flip: i % 2 === 1 })).join("")}${Array.from({ length: 50 }, (_, i) => `<circle class="flake" cx="${(i * 131) % 1920}" cy="${(i * 71) % 900}" r="${4 + (i % 3) * 2}" fill="#fff"/>`).join("")}${sticker(960, 170, "NO WINTER UNIFORMS", { size: 54, rot: -2, bg: ink })}<g id="pop-note" transform="translate(1500 420) rotate(5)"><rect x="-250" y="-60" width="500" height="120" fill="#fbf6e8" stroke="${ink}" stroke-width="6"/><text y="16" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="${K.red}">"BEFORE WINTER"</text></g>`;
    return H.defs() + H.sky("#8a8f96", "#b8bcc2") + ground("#5a4630", "") + tanks + mudFront +
      rain + snow + place(CAST.klaus({ pose: "hold", brows: "worried", mouth: "flat", prop: P.gauge(100, 230, 0.55, 0.4) }), 880, 1050, 1.45, { id: "klaus" }) +
      `<ellipse cx="880" cy="1060" rx="230" ry="60" fill="#6b5236" stroke="${ink}" stroke-width="6"/><g id="fade-snow2"><ellipse cx="880" cy="1060" rx="230" ry="70" fill="#e8f0f6" stroke="${ink}" stroke-width="6"/></g>` +
      `<g id="fade-map" data-layout-allow-overlap="true">${map}${sticker(560, 960, "MILLIONS KILLED OR CAPTURED", { size: 44, rot: -2, bg: ink, id: "st-mil" })}</g>` +
      H.cut("cut-cold", cold) + `<g id="fade-map2" data-layout-allow-overlap="true">${map}${back}${sticker(560, 960, "DECEMBER 1941", { size: 48, rot: -2, bg: ink })}</g>` +
      H.date(300, 120, "AUTUMN 1941", "st-date") + H.grain();
  };

  // F03 — The parade: Red Square
  S["03"] = () => {
    const domes = [[1280, 300, "#c8352b"], [1420, 250, "#2f6b3a"], [1560, 300, "#e2b33c"], [1690, 330, "#3d6fa3"]].map(([x, y, c]) => `<rect x="${x - 40}" y="${y}" width="80" height="${520 - y}" fill="#efe0c0" stroke="${ink}" stroke-width="5"/><path d="M${x} ${y - 110} C${x + 70} ${y - 60} ${x + 60} ${y} ${x} ${y} C${x - 60} ${y} ${x - 70} ${y - 60} ${x} ${y - 110}Z" fill="${c}" stroke="${ink}" stroke-width="6"/><path d="M${x} ${y - 110} V${y - 150}" stroke="${ink}" stroke-width="5"/>`).join("");
    const marchers = Array.from({ length: 12 }, (_, i) => place(CAST.soldierSU({ pose: "idle", brows: "neutral", mouth: "flat" }), 80 + (i % 6) * 190 + (i >= 6 ? 90 : 0), i >= 6 ? 1060 : 960, i >= 6 ? 0.9 : 0.78)).join("");
    return H.defs() + H.sky("#9aa3ad", "#d7dce2") + domes +
      `<rect x="0" y="380" width="1200" height="140" fill="#9a3a2e" stroke="${ink}" stroke-width="6"/>${Array.from({ length: 15 }, (_, i) => `<path d="M${i * 80} 380 v-30 h40 v30" fill="#9a3a2e" stroke="${ink}" stroke-width="5"/>`).join("")}` +
      `<path d="M0 520 H1920 V1080 H0Z" fill="#eef2f6" stroke="${ink}" stroke-width="5"/>` +
      // Lenin's tomb, a stepped block; Stalin and the officer on top
      `<g><rect x="260" y="450" width="560" height="160" fill="#6a2a26" stroke="${ink}" stroke-width="6"/><rect x="320" y="400" width="440" height="60" fill="#7a3530" stroke="${ink}" stroke-width="6"/><rect x="400" y="360" width="280" height="44" fill="#6a2a26" stroke="${ink}" stroke-width="6"/></g>` +
      place(CAST.stalin({ pose: "idle", brows: "neutral", mouth: "flat", cap: "peaked", capCol: "#8a8460", capBand: "#8a8460" }), 460, 470, 0.95, { id: "stalin" }) +
      place(CAST.sovietOfficer({ pose: "hold" }), 650, 470, 0.95, { id: "sovoff", flip: true }) +
      place(CAST.stalin({ pose: "point", brows: "neutral", mouth: "flat", cap: "peaked", capCol: "#8a8460", capBand: "#8a8460" }), 460, 470, 0.95, { id: "stalin-pt" }) +
      `<g id="march">${marchers}</g>` +
      `<g id="pop-sign" transform="translate(1660 820)"><rect x="-10" y="-20" width="20" height="240" fill="${C.wood}" stroke="${ink}" stroke-width="5"/><path d="M-160 -120 H130 L190 -70 L130 -20 H-160Z" fill="#fffaf0" stroke="${ink}" stroke-width="6"/><text x="-10" y="-56" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="${K.red}">THE FRONT</text></g>` +
      Array.from({ length: 40 }, (_, i) => `<circle class="flake" cx="${(i * 137) % 1920}" cy="${(i * 61) % 800}" r="${4 + (i % 3) * 2}" fill="#fff"/>`).join("") +
      H.date(1500, 110, "MOSCOW, 7 NOV 1941", "st-date") + H.grain();
  };

  // F04 — The Holocaust (straight): routes converge on the camps in occupied Poland
  S["04"] = () => {
    const E = "europe";
    const camps = ["Auschwitz", "Treblinka", "Sobibor", "Belzec", "Chelmno", "Majdanek"];
    const off = { Auschwitz: [-40, 44], Treblinka: [70, -14], Sobibor: [80, 10], Belzec: [70, 42], Chelmno: [-80, -16], Majdanek: [-20, 44] };
    const from = [["Amsterdam", "Auschwitz"], ["Paris", "Auschwitz"], ["Berlin", "Auschwitz"], ["Vienna", "Auschwitz"], ["Prague", "Treblinka"], ["Budapest", "Auschwitz"], ["Athens", "Auschwitz"], ["Rome", "Auschwitz"], ["Oslo", "Auschwitz"], ["Warsaw", "Treblinka"], ["Berlin", "Sobibor"], ["Amsterdam", "Sobibor"]];
    const routes = from.map(([a, b], i) => { const A = Geo.PLACES[a], B = Geo.PLACES[b]; const mid = [(A[0] + B[0]) / 2 + (i % 2 ? 1.2 : -1.2), (A[1] + B[1]) / 2 + 0.8]; return `<g id="arr-r${i}"><path d="${Geo.route([A, mid, B], E)}" stroke="#c9c2b0" stroke-width="5" fill="none" stroke-linecap="round" opacity=".85"/></g>`; }).join("");
    const occ = [[24, 56.5], [28, 59], [33, 57], [35, 55], [34.5, 52], [37, 50], [38, 47.5], [33.5, 46.4], [30, 46.4], [27, 48], [23.5, 50], [22.5, 53]];
    return H.defs() + H.map(E, { de: "#3a3d44", at: "#3a3d44", pl: "#4a4048", cz: "#3a3d44" }, { sea: "#10151e", land: "#2a2e36" }) +
      `<g id="fade-occ">${H.region(occ, E, "#4a3a3a", "", 0.85)}${(() => { const [x, y] = Geo.project([31, 52], E); return `<text x="${x.toFixed(0)}" y="${y.toFixed(0)}" text-anchor="middle" class="t-map" font-size="30">OCCUPIED SOVIET UNION</text>`; })()}</g>` +
      H.counter(1500, 930, "MURDERED BY KILLING SQUADS, BY END OF 1942", "MORE THAN 1,000,000", "cnt-squads", 760) +
      `<g id="fade-routes">${routes}</g>` +
      camps.map((c, i) => H.pin(c, E, { id: `pop-k${i}`, col: "#e9e2cf", dx: off[c][0], dy: off[c][1], size: 26, r: 9 })).join("") +
      `<g id="fade-doc" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#14161c" opacity=".9"/>${H.doc(960, 540, 860, 820, [0, 1, 2, "“Final Solution of the Jewish Question”", 0, 1, 0, 2, 1, 0], { title: "WANNSEE, 20 JANUARY 1942", rot: -1.5, size: 32 })}<text x="960" y="1040" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="30" fill="#c9c2b0">Minutes of the Wannsee Conference, Berlin</text></g>` +
      H.counter(1460, 930, "JEWS MURDERED BY 1945", "ABOUT 6,000,000", "cnt-6m", 640) +
      `<g id="fade-others" transform="translate(470 930)"><rect x="-400" y="-80" width="800" height="160" rx="16" fill="#151820" stroke="#555" stroke-width="5"/><text y="-24" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="28" fill="#c9c2b0">ALSO PERSECUTED AND MURDERED</text><text y="34" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="30" fill="#fffaf0">Roma · disabled people · Soviet POWs · Poles</text></g>` +
      `<g id="fade-ttl">${sticker(960, 110, "THE HOLOCAUST", { size: 52, rot: 0, bg: "#2a2c33" })}</g>` +
      H.vignette(0.6) + H.grain();
  };

  // F05 — Japan's whiteboard
  S["05"] = () => {
    const Pc = "pacific";
    const china = `<g id="fade-china" data-layout-allow-overlap="true">${H.mapX(Pc, { jp: JP, kr: JP, tw: JP, cn: "#d9cfb4" }, { sea: "#22313f", extra: [{ pts: [[120, 41.5], [124, 40], [122, 37], [121, 31], [121, 28], [119, 25], [116, 23], [113, 22], [110, 21], [109.5, 23.5], [112, 28], [113, 31], [111, 34], [113, 37], [114, 40], [117, 41.5]], fill: JP, op: 0.75 }, { pts: [[119, 42], [124, 40], [131, 42.5], [134, 48], [127, 50], [122, 53], [119, 50], [116.5, 47]], fill: JP, op: 0.75 }] })}${H.pin("Nanjing", Pc, { col: "#e9e2cf", dy: 44, size: 34 })}${H.pin("Tokyo", Pc, { dy: -24 })}${sticker(560, 980, "CHINA, AT WAR SINCE 1937", { size: 46, rot: -2, bg: ink })}</g>`;
    const oil = `<g id="cut-oil" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#e9dcc0"/>${[640, 960, 1280].map((x) => `<g transform="translate(${x} 760)"><rect x="-110" y="-300" width="220" height="300" rx="16" fill="#3d6fa3" stroke="${ink}" stroke-width="8"/><path d="M-110 -200 H110 M-110 -100 H110" stroke="${ink}" stroke-width="6"/><text y="-130" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="48" fill="#fffaf0">OIL</text></g>`).join("")}<rect y="760" width="1920" height="320" fill="#b8946a" stroke="${ink}" stroke-width="5"/>${P.stamp(960, 560, 1.7, "EMBARGO", K.red, { id: "st-oil", rot: -10 })}${sticker(960, 150, "US OIL: CUT OFF", { size: 52, rot: -2, bg: ink })}</g>`;
    const board = `<rect x="420" y="130" width="1080" height="560" rx="12" fill="#fbfbf6" stroke="${ink}" stroke-width="10"/><rect x="420" y="690" width="1080" height="24" fill="#9a9a9a" stroke="${ink}" stroke-width="5"/><text x="960" y="200" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="48" fill="#1f3f7f">THE PLAN</text>` +
      `<g id="pop-s1"><text x="480" y="300" font-family="Fredoka" font-weight="600" font-size="46" fill="${ink}">1. Seize the oil (S.E. Asia)</text></g>` +
      `<g id="pop-s2"><text x="480" y="400" font-family="Fredoka" font-weight="600" font-size="46" fill="${ink}">2. Destroy the US fleet</text></g>` +
      `<g id="pop-s3"><text x="480" y="500" font-family="Fredoka" font-weight="600" font-size="46" fill="${K.red}">3. America gets sad,</text><text x="530" y="560" font-family="Fredoka" font-weight="600" font-size="46" fill="${K.red}">goes home</text><g transform="translate(1310 520)"><circle r="58" fill="none" stroke="${K.red}" stroke-width="6"/><circle cx="-20" cy="-14" r="6" fill="${K.red}"/><circle cx="20" cy="-14" r="6" fill="${K.red}"/><path d="M-26 30 Q0 6 26 30" stroke="${K.red}" stroke-width="6" fill="none"/></g></g>`;
    const plan = `<g id="pop-plan" transform="translate(1520 330) rotate(5)"><rect x="-200" y="-140" width="400" height="280" fill="#f6efdc" stroke="${ink}" stroke-width="6"/><text y="-80" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="${ink}">TARGET:</text><text y="10" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="58" fill="${K.red}">HAWAII</text><path d="M-130 70 q60 -40 120 0 t120 0" stroke="#3d6fa3" stroke-width="6" fill="none"/></g>`;
    return H.defs() + H.room("#d9cdb4", "#8a6a48") + board +
      place(CAST.tojo({ pose: "point", prop: `<rect x="206" y="152" width="30" height="12" rx="4" fill="${K.red}" stroke="${ink}" stroke-width="3" transform="rotate(-20 214 166)"/>` }), 330, 1040, 1.4, { id: "tojo" }) +
      place(CAST.yamamoto({ pose: "cross" }), 1640, 1040, 1.4, { id: "yama", flip: true }) + plan +
      china + oil + H.date(300, 110, "TOKYO, 1941", "st-date") + H.grain();
  };

  // F06 — Pearl Harbor
  S["06"] = () => {
    const harbor = H.sky("#f5c9a0", "#fbe6cf") + `<path d="M0 520 Q300 380 640 460 Q900 360 1240 450 Q1600 380 1920 470 V560 H0Z" fill="#5f8f4a" stroke="${ink}" stroke-width="5"/><rect y="540" width="1920" height="540" fill="#3d7aa8"/>` +
      Array.from({ length: 4 }, (_, i) => `<path class="wave" d="M-100 ${640 + i * 110} q60 -14 120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0" stroke="#d9ecf7" stroke-width="5" fill="none" opacity=".6"/>`).join("") +
      [[300, 700], [820, 720], [1340, 700], [560, 900], [1100, 920], [1620, 900]].map(([x, y], i) => H.bship(x, y, 0.75, "", i % 2 ? "#8a8e96" : "#7c818a")).join("") +
      `<g id="fires">${[[300, 690], [820, 710], [1340, 690], [560, 890], [1100, 910], [1620, 890], [420, 700], [1220, 700]].map(([x, y]) => `<g>${H.smoke(x, y - 60, 0.9)}${H.fire(x, y - 40, 0.9)}</g>`).join("")}</g>` +
      `<g id="inr-planes">${[[1300, 200], [1500, 260], [1700, 180], [1100, 290]].map(([x, y]) => H.plane(x, y, 0.55, "#c9c6b0", true)).join("")}</g>`;
    const radar = `<rect width="960" height="1080" fill="#6b5a42"/><rect x="0" y="760" width="960" height="320" fill="#4a3b28"/><g transform="translate(330 470)"><rect x="-200" y="-200" width="400" height="400" rx="20" fill="#2a2e2a" stroke="${ink}" stroke-width="8"/><circle r="160" fill="#0f2a1a" stroke="#3a6a4a" stroke-width="6"/><circle r="100" fill="none" stroke="#2f5f3f" stroke-width="3"/><path d="M0 0 L150 -60" stroke="#6fe08f" stroke-width="5"/><g id="pop-blip"><ellipse cx="80" cy="-70" rx="46" ry="30" fill="#8fff9f" opacity=".85"/></g></g>${place(CAST.radarOp({ pose: "point" }), 700, 1060, 1.3, { id: "radar", flip: true })}` +
      `<rect x="960" width="960" height="1080" fill="#b8a888"/><rect x="960" y="780" width="960" height="300" fill="#8a6a48"/><path d="M960 0 V1080" stroke="${ink}" stroke-width="12"/>${H.table(1180, 760, 520, "#6b4a2c")}${H.phone(1300, 740, 0.9)}<g transform="translate(1440 735)"><rect x="-26" y="-40" width="52" height="40" rx="6" fill="#fff" stroke="${ink}" stroke-width="4"/></g>${place(CAST.dutyOfficer({ pose: "hold" }), 1640, 1060, 1.3, { id: "duty", flip: true })}` +
      sticker(480, 110, "OPANA RADAR, 7:02 A.M.", { size: 40, rot: -2, bg: ink }) +
      `<g id="pop-b17" transform="translate(1440 300)"><rect x="-300" y="-150" width="600" height="300" rx="16" fill="#9fc6e2" stroke="${ink}" stroke-width="7"/>${H.bomber(-90, -20, 0.6, "#a8a8a0")}${H.bomber(130, 50, 0.5, "#a8a8a0")}<text y="120" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="${ink}">EXPECTED: B-17s FROM CALIFORNIA</text></g>`;
    const sea = `<rect width="1920" height="1080" fill="#2f6f9f"/>${Array.from({ length: 6 }, (_, i) => `<path class="wave" d="M-100 ${200 + i * 150} q60 -14 120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0" stroke="#cfe6f4" stroke-width="5" fill="none" opacity=".6"/>`).join("")}${H.carrier(560, 420, 0.8)}${H.carrier(1300, 560, 0.9)}${H.carrier(760, 820, 0.85)}${sticker(960, 140, "THE CARRIERS: AWAY AT SEA", { size: 50, rot: -2, bg: ink })}`;
    const shop = H.sky("#9fd0ea", "#e3f2f9") + `<rect y="880" width="1920" height="200" fill="#9a9a9a" stroke="${ink}" stroke-width="5"/><rect x="260" y="260" width="1400" height="620" fill="#f3e6c8" stroke="${ink}" stroke-width="8"/><path d="M260 260 L1660 260 L1620 360 L300 360Z" fill="#c8352b" stroke="${ink}" stroke-width="6"/>${Array.from({ length: 14 }, (_, i) => `<path d="M${300 + i * 95} 260 L${300 + i * 95 + 40} 360" stroke="#fff" stroke-width="22" opacity=".85"/>`).join("")}<rect x="320" y="420" width="560" height="380" fill="#bfe0ef" stroke="${ink}" stroke-width="7"/><rect x="1040" y="420" width="560" height="380" fill="#bfe0ef" stroke="${ink}" stroke-width="7"/>` +
      `<g id="sign-old"><g transform="translate(960 160)"><rect x="-480" y="-70" width="960" height="140" rx="16" fill="#1f3f7f" stroke="${ink}" stroke-width="8"/><text y="12" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="58" fill="#fffaf0">WE'RE NEUTRAL!</text><text y="54" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="30" fill="#9effa0">(BORROWING AVAILABLE.)</text></g></g>` +
      `<g id="pop-open" transform="translate(960 160)"><rect x="-480" y="-70" width="960" height="140" rx="16" fill="${K.red}" stroke="${ink}" stroke-width="8"/><text y="26" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="76" fill="#fffaf0">OPEN FOR WAR</text></g>` +
      place(CAST.fdr({ pose: "idle", brows: "angry", mouth: "flat", holder: false }), 1240, 1060, 1.5, { flip: true });
    const hq = H.room("#a89a82", "#6b5a42") + `<rect x="300" y="130" width="560" height="380" fill="#efe6d2" stroke="${ink}" stroke-width="7"/><text x="580" y="210" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="${ink}">DECLARATION OF WAR</text><text x="580" y="290" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="34" fill="#555">To: The United States</text><path d="M380 360 H780 M380 410 H700" stroke="#bbb" stroke-width="10"/>` +
      place(CAST.hitler({ pose: "hips", mouth: "grin", brows: "smug" }), 560, 1040, 1.45) + place(CAST.klaus({ pose: "shrug", brows: "worried", mouth: "open" }), 1340, 1040, 1.4, { flip: true }) + sticker(1460, 160, "BERLIN, 11 DEC 1941", { size: 44, rot: 2, bg: ink });
    return H.defs() + harbor + H.counter(1500, 160, "AMERICANS KILLED", "ABOUT 2,400", "cnt-killed", 460) + sticker(560, 160, "8 BATTLESHIPS DAMAGED OR SUNK", { size: 42, rot: -2, bg: ink, id: "st-8" }) + H.cut("cut-radar", radar) + H.cut("cut-sea", sea) + H.cut("cut-shop", shop) + H.cut("cut-hq", hq) +
      H.date(400, 110, "PEARL HARBOR, 7 DEC 1941", "st-date") + H.grain();
  };

  // F07 — The factory
  S["07"] = () => {
    const shopSmall = `<g id="shop"><rect x="760" y="560" width="400" height="300" fill="#f3e6c8" stroke="${ink}" stroke-width="6"/><path d="M760 560 H1160 L1140 600 H780Z" fill="#c8352b" stroke="${ink}" stroke-width="5"/><g transform="translate(960 530)"><rect x="-150" y="-26" width="300" height="52" rx="8" fill="${K.red}" stroke="${ink}" stroke-width="5"/><text y="12" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="30" fill="#fffaf0">OPEN FOR WAR</text></g><rect x="800" y="640" width="140" height="160" fill="#bfe0ef" stroke="${ink}" stroke-width="5"/><rect x="980" y="640" width="140" height="160" fill="#bfe0ef" stroke="${ink}" stroke-width="5"/></g>`;
    const factory = `<g id="pop-factory"><rect x="0" y="200" width="1920" height="680" fill="#c9b49a" stroke="${ink}" stroke-width="8"/>${Array.from({ length: 8 }, (_, i) => `<path d="M${i * 240} 200 L${i * 240 + 120} 110 L${i * 240 + 240} 200Z" fill="#a8927a" stroke="${ink}" stroke-width="6"/>`).join("")}${[200, 640, 1080, 1520].map((x) => `<rect x="${x}" y="40" width="70" height="170" fill="#8a7a6a" stroke="${ink}" stroke-width="5"/>`).join("")}<g transform="translate(960 270)"><rect x="-520" y="-50" width="1040" height="100" rx="14" fill="${K.red}" stroke="${ink}" stroke-width="7"/><text y="24" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="64" fill="#fffaf0">OPEN FOR WAR</text></g><rect x="0" y="700" width="1920" height="40" fill="#555" stroke="${ink}" stroke-width="5"/></g>`;
    const line = `<g id="inl-tanks">${[360, 900, 1440].map((x) => H.tank(x, 650, 0.55, "", "#6b6b3a")).join("")}</g>` + `<g id="pop-planes">${[400, 960, 1520].map((x) => H.plane(x, 470, 1.0, "#a8acb4")).join("")}</g>`;
    const workers = `<g id="inl-workers">${[260, 680, 1240, 1660].map((x, i) => place(CAST.worker({ pose: i % 2 ? "hold" : "raise", hairCol: ["#6a3a1e", "#2a1d12", "#c9862f", "#4a2f1d"][i], skin: i === 2 ? "#8a5634" : C.skin, legs: "#2e4868" }), x, 1060, 1.15)).join("")}</g>`;
    const hq = H.room("#a89a82", "#6b5a42") + place(CAST.hitler({ pose: "hips", mouth: "shout", brows: "furious" }), 560, 1040, 1.45, { id: "hitler" }) +
      place(CAST.klaus({ pose: "hold", brows: "worried", prop: P.clipboard(110, 222, 0.9) }), 1360, 1040, 1.4, { id: "klaus", flip: true }) +
      `<g id="pop-photo" transform="translate(1000 330) rotate(-4)"><rect x="-150" y="-110" width="300" height="220" fill="#fff" stroke="${ink}" stroke-width="6"/><rect x="-130" y="-90" width="260" height="160" fill="#9a9a90"/>${[[-80, -40], [0, -40], [80, -40], [-80, 20], [0, 20], [80, 20]].map(([x, y]) => `<g transform="translate(${x} ${y}) rotate(90) scale(.22)">${H.plane(0, 0, 1, "#d8d8d0").replace(/^<g/, "<g")}</g>`).join("")}</g>`;
    const lot = `<rect width="1920" height="1080" fill="#a8a8a0"/>${Array.from({ length: 4 }, (_, r) => Array.from({ length: 7 }, (_, c) => H.plane(170 + c * 265, 170 + r * 250, 0.95, "#d8dad0")).join("")).join("")}<g transform="translate(960 1000)"><rect x="-430" y="-50" width="860" height="100" rx="14" fill="${ink}"/><text y="18" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="48" fill="#fffaf0">A VERY LARGE PARKING LOT</text></g>`;
    const U = "usa";
    const campsUS = [[-118.15, 36.73], [-121.37, 41.89], [-114.4, 33.99], [-111.9, 33.1], [-108.9, 44.67], [-114.24, 42.68], [-112.75, 39.42], [-102.32, 38.05], [-91.27, 33.77], [-91.47, 33.4]];
    const intern = H.map(U, { us: "#5a5f6a", ca: "#3a3f48", mx: "#3a3f48" }, { sea: "#141a24", land: "#2c313a" }) + campsUS.map((p, i) => { const [x, y] = Geo.project(p, U); return `<g id="pop-j${i}"><rect x="${(x - 14).toFixed(0)}" y="${(y - 14).toFixed(0)}" width="28" height="28" fill="#e9e2cf" stroke="${ink}" stroke-width="4"/></g>`; }).join("") +
      H.counter(1460, 940, "JAPANESE AMERICANS INTERNED", "ABOUT 120,000", "cnt-int", 620) + sticker(500, 110, "INTERNMENT CAMPS, 1942", { size: 46, rot: -1, bg: "#2a2c33" }) +
      H.doc(520, 760, 600, 360, ["Civil Liberties Act of 1988", 0, "a formal apology", 1], { id: "pop-apology", title: "1988", rot: -3, size: 30 });
    return H.defs() + H.sky("#9fd0ea", "#e3f2f9") + `<rect y="860" width="1920" height="220" fill="#9a9a9a" stroke="${ink}" stroke-width="5"/>` + factory + line + shopSmall + workers +
      H.cut("cut-hq", hq) + H.cut("cut-lot", lot) + `<g id="fade-intern" data-layout-allow-overlap="true">${intern}</g>` + H.grain();
  };

  // F08 — Six months: Japan races across Asia; Yamamoto's calendar
  S["08"] = () => {
    const Pc = "pacific";
    const reg = (keys, id) => `<g id="${id}">${keys.filter((k) => g.EU[Pc].c[k]).map((k) => `<path d="${g.EU[Pc].c[k]}" fill="${JP}" stroke="${ink}" stroke-width="2.5"/>`).join("")}</g>`;
    const ar = (pts, id) => H.arrow(pts, Pc, { id, col: JP, w: 18 });
    const map = H.mapX(Pc, { jp: JP, kr: JP, tw: JP, ic: "#9a6a50", th: "#9a7a60" }, { sea: "#2b4a6b", extra: [{ pts: [[120, 41.5], [124, 40], [122, 37], [121, 31], [121, 28], [119, 25], [116, 23], [113, 22], [110, 21], [109.5, 23.5], [112, 28], [113, 31], [111, 34], [113, 37], [114, 40], [117, 41.5]], fill: JP, op: 0.8 }] }) +
      ar([[114, 24.5], [114.2, 22.6]], "arr-hk") + ar([[121, 22.5], [121, 16.5]], "arr-ph") + ar([[104, 12], [102, 5.5], [103.8, 1.6]], "arr-sg") + ar([[106, 2], [107, -5]], "arr-dei") + ar([[99, 13], [97, 16.3]], "arr-bu") +
      reg(["ph"], "fade-ph") + reg(["my"], "fade-my") + reg(["idn"], "fade-dei") + reg(["mm"], "fade-bu") +
      H.pin("Hong Kong", Pc, { dx: 40, dy: 40, size: 28 }) + H.pin("Manila", Pc, { dx: 70, size: 28 }) + H.pin("Singapore", Pc, { dy: 44, size: 28 }) + H.pin("Rangoon", Pc, { dx: -10, dy: -24, size: 28 }) + H.pin("Tokyo", Pc, { size: 28 }) +
      sticker(600, 860, "ABOUT 80,000 SURRENDERED", { size: 44, rot: -2, bg: ink, id: "st-sg" });
    const cal = H.room("#d9cdb4", "#8a6a48") + H.calendar(960, 400, "1942", "5", { id: "cal5", s: 1.3 }) + `<g id="cut-cal6">${H.calendar(960, 400, "1942", "6", { s: 1.3 })}</g><g id="pop-x6"><path d="M840 280 L1080 540 M1080 280 L840 540" stroke="${K.red}" stroke-width="22" stroke-linecap="round"/></g>` +
      `<text x="960" y="620" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="${ink}">MONTHS</text>` +
      place(CAST.yamamoto({ pose: "raise", brows: "worried" }), 1440, 1040, 1.4, { id: "yama", flip: true }) + place(CAST.tojo({ pose: "armsUp", mouth: "grin", brows: "happy" }), 420, 1040, 1.4, { id: "tojo" });
    return H.defs() + cal + `<g id="cut-map" data-layout-allow-overlap="true">${map}</g>` + H.date(330, 110, "DEC 1941 – MAY 1942", "st-date") + H.grain();
  };

  // F09 — The raid
  S["09"] = () => {
    const deck = `<rect y="560" width="1920" height="520" fill="#2f6f9f"/>${Array.from({ length: 4 }, (_, i) => `<path class="wave" d="M-100 ${600 + i * 120} q60 -14 120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0" stroke="#cfe6f4" stroke-width="5" fill="none" opacity=".6"/>`).join("")}` +
      `<path d="M120 700 L1800 700 L1700 860 L200 860Z" fill="#7a7e86" stroke="${ink}" stroke-width="8"/><rect x="80" y="640" width="1760" height="62" fill="#9a8a6a" stroke="${ink}" stroke-width="7"/><path d="M120 671 H1800" stroke="#fffaf0" stroke-width="5" stroke-dasharray="40 26"/><rect x="1380" y="470" width="120" height="170" fill="#7a7e86" stroke="${ink}" stroke-width="7"/>`;
    const b25 = `<g id="b25"><g transform="translate(540 560)"><path d="M-300 20 C-220 -40 220 -40 300 0 C220 40 -220 50 -300 20Z" fill="#7c7a52" stroke="${ink}" stroke-width="8"/><path d="M-260 10 L-300 -90 L-250 -90 L-210 0Z" fill="#7c7a52" stroke="${ink}" stroke-width="6"/><path d="M-80 0 L120 0 L80 70 L-60 70Z" fill="#6c6a44" stroke="${ink}" stroke-width="6"/><rect x="-60" y="10" width="80" height="34" rx="14" fill="#555" stroke="${ink}" stroke-width="5"/><rect x="60" y="10" width="80" height="34" rx="14" fill="#555" stroke="${ink}" stroke-width="5"/><path d="M230 -10 Q260 -18 280 -2" stroke="#bfe3f2" stroke-width="12" fill="none"/></g></g>`;
    const route = `<g id="fade-route" data-layout-allow-overlap="true">${H.map("pacific", { jp: JP, cn: "#d9cfb4", kr: JP, tw: JP }, { sea: "#22313f" })}${H.pin("Tokyo", "pacific", { dy: -26 })}<path d="${Geo.route([[153, 35.5], [145, 36], [139.7, 35.7], [128, 31], [120, 29]], "pacific")}" stroke="#fffaf0" stroke-width="10" stroke-dasharray="26 16" fill="none"/>${(() => { const [x, y] = Geo.project([120, 29], "pacific"); return `<text x="${x.toFixed(0)}" y="${(y + 60).toFixed(0)}" text-anchor="middle" class="t-map" font-size="40">CHINA. ISH.</text>`; })()}${(() => { const [x, y] = Geo.project([153, 35.5], "pacific"); return `<text x="${x.toFixed(0)}" y="${(y + 60).toFixed(0)}" text-anchor="middle" class="t-map" font-size="32">CARRIER</text>`; })()}</g>`;
    const gamble = `<g id="fade-gamble" data-layout-allow-overlap="true">${H.map("pacific", { jp: JP, kr: JP, tw: JP }, { sea: "#2b4a6b" })}${H.pin("Tokyo", "pacific")}${H.pin("Midway", "pacific", { dy: -30, size: 36 })}${H.pin("Pearl Harbor", "pacific", { dy: 50, size: 30 })}${H.arrow([[142, 33], [160, 31], [-179, 28.5]], "pacific", { id: "arr-mid", col: JP, w: 22 })}<g id="pop-q">${(() => { const [x, y] = Geo.at("Midway", "pacific"); return `<text x="${x.toFixed(0)}" y="${(y - 80).toFixed(0)}" text-anchor="middle" class="t-title" font-size="110">?</text>`; })()}</g></g>`;
    return H.defs() + H.sky("#8fc3e6", "#dff0f9") + H.clouds([[300, 200, 1.1], [1500, 150, 1.2]]) + deck + b25 +
      place(CAST.pilotUS({ pose: "shrug" }), 1180, 690, 1.15, { id: "pilot" }) + place(CAST.doolittle({ pose: "hips" }), 1560, 690, 1.25, { id: "dool", flip: true }) +
      sticker(560, 260, "16 ARMY BOMBERS", { size: 48, rot: -3, bg: ink, id: "st-16" }) +
      route + gamble + H.date(330, 110, "APRIL 1942", "st-date") + H.grain();
  };

  // F10 — The water trick (Midway)
  S["10"] = () => {
    const room = `<rect width="1920" height="1080" fill="#2a2d34"/><rect y="820" width="1920" height="260" fill="#1d1f24" stroke="${ink}" stroke-width="5"/>` +
      `<g transform="translate(960 330)"><rect x="-560" y="-250" width="1120" height="500" fill="#3d6fa3" stroke="${ink}" stroke-width="10"/>${Array.from({ length: 9 }, (_, i) => `<path d="M${-560 + i * 140} -250 V250" stroke="#5a8ac0" stroke-width="2"/>`).join("")}<circle cx="120" cy="20" r="10" fill="#e2d6a8" stroke="${ink}" stroke-width="3"/><text x="120" y="-20" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="#fffaf0">MIDWAY</text><g id="pop-af"><text x="-300" y="-120" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="90" fill="#ffcc33">AF = ?</text></g><g id="pop-afq">${[[-420, 120], [380, -150], [420, 160], [-60, 170]].map(([x, y]) => `<text x="${x}" y="${y}" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="70" fill="#fffaf0">?</text>`).join("")}</g><g id="pop-afok"><circle cx="120" cy="20" r="60" fill="none" stroke="#ffcc33" stroke-width="10"/><text x="120" y="130" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="54" fill="#ffcc33">AF</text></g></g>` +
      H.table(200, 780, 1520, "#4a3a2a") + Array.from({ length: 5 }, (_, i) => `<rect x="${300 + i * 280}" y="720" width="140" height="60" fill="#f6efdc" stroke="${ink}" stroke-width="4" transform="rotate(${-6 + i * 3} ${370 + i * 280} 750)"/>`).join("") +
      place(CAST.codebreakerUS({ pose: "point" }), 470, 1060, 1.45, { id: "cb" }) + place(WW.person({ body: "#33415c", sleeve: "#33415c", legs: "#25304a", hair: "neat", glasses: true, torsoKind: "tunic", brows: "neutral" }), 1500, 1060, 1.3, { flip: true }) +
      `<g id="pop-msg" transform="translate(1420 650) rotate(4)"><rect x="-260" y="-80" width="520" height="160" fill="#fffaf0" stroke="${ink}" stroke-width="6"/><text y="-22" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="26" fill="#555">MIDWAY → PEARL HARBOR</text><text y="34" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="${ink}">WATER MACHINE BROKEN</text></g>`;
    const intercept = `<g id="cut-int" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#20222a"/>${P.radio(960, 380, 2.2)}<g transform="translate(960 800) rotate(-2)"><rect x="-560" y="-80" width="1120" height="160" fill="#f6efdc" stroke="${ink}" stroke-width="6"/><text y="20" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="60" fill="${ink}">"AF IS SHORT OF WATER"</text></g>${sticker(960, 130, "INTERCEPTED JAPANESE MESSAGE", { size: 44, rot: -1, bg: K.red })}</g>`;
    const sea = `<g id="fade-battle" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#2f6f9f"/>${Array.from({ length: 6 }, (_, i) => `<path class="wave" d="M-100 ${180 + i * 160} q60 -14 120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0 t120 0" stroke="#cfe6f4" stroke-width="5" fill="none" opacity=".6"/>`).join("")}` +
      [[420, 560], [1000, 480], [1500, 640], [760, 860]].map(([x, y], i) => H.carrier(x, y, 0.7, "", "#8a8070") + `<g id="pop-f${i}">${H.smoke(x - 40, y - 30, 1)}${H.fire(x - 60, y - 20, 1)}${H.fire(x + 80, y - 20, 0.8)}</g>`).join("") +
      `<g id="dive">${[[300, 120], [900, 90], [1500, 140]].map(([x, y]) => `<g transform="translate(${x} ${y}) rotate(50)">${H.plane(0, 0, 0.6, "#3d5f8a")}</g>`).join("")}</g>${sticker(400, 1000, "ABOUT 5 MINUTES", { size: 46, rot: -2, bg: ink, id: "st-5m" })}${sticker(1500, 1000, "JAPAN: 4 CARRIERS LOST", { size: 46, rot: 2, bg: K.red, id: "st-4" })}</g>`;
    const guad = `<g id="fade-guad" data-layout-allow-overlap="true">${H.map("pacific", { jp: JP, kr: JP, tw: JP, ph: JP, idn: JP, png: "#c9b98a", sol: "#c9b98a", au: "#a08b5b" }, { sea: "#2b4a6b" })}${H.pin("Guadalcanal", "pacific", { dx: -150, dy: 20, size: 34 })}${H.arrow([[178, -20], [168, -14], [160.4, -9.9]], "pacific", { id: "arr-guad", col: "#3d6fa3", w: 22 })}${sticker(1400, 160, "GUADALCANAL, AUG 1942", { size: 46, rot: 2, bg: ink })}</g>`;
    return H.defs() + room + intercept + sea + guad + H.date(300, 110, "PEARL HARBOR, JUNE 1942", "st-date") + H.tp(1) + H.grain();
  };

  // F11 — The other codebreakers
  S["11"] = () => {
    const A = "atlantic";
    const map = H.map(A, { uk: "#a08b5b", us: "#3d6fa3", ca: "#3d6fa3", fr: AX, de: AX, no: AX, benl: AX, dk: AX }, { sea: "#22405e" }) +
      H.line([[-63.6, 44.6], [-50, 50], [-30, 55], [-15, 56], [-3, 53.4]], A, { col: "#fffaf0", w: 8, dash: "24 14" }) +
      `<g id="pop-ub">${[[-38, 52], [-28, 56], [-45, 49], [-20, 52.5]].map((p) => { const [x, y] = Geo.project(p, A); return `<g transform="translate(${x.toFixed(0)} ${y.toFixed(0)})"><path d="M-46 0 Q0 -18 46 0 Q0 14 -46 0Z" fill="#3a3d44" stroke="${ink}" stroke-width="4"/><rect x="-8" y="-20" width="16" height="14" fill="#3a3d44" stroke="${ink}" stroke-width="3"/></g>`; }).join("")}</g>` +
      H.pin("Halifax", A, { dy: 44, size: 28 }) + H.pin("Liverpool", A, { dy: 44, size: 28 }) + sticker(960, 110, "THE BATTLE OF THE ATLANTIC", { size: 48, rot: -1, bg: ink });
    const house = `<g id="fade-house" data-layout-allow-overlap="true">${H.sky("#a9c3d6", "#e3edf3")}${H.ground(760)}<g><rect x="500" y="320" width="920" height="440" fill="#b5643a" stroke="${ink}" stroke-width="8"/><path d="M460 330 L960 140 L1460 330Z" fill="#6a4a3a" stroke="${ink}" stroke-width="8"/>${Array.from({ length: 6 }, (_, i) => `<rect x="${560 + i * 140}" y="400" width="80" height="110" fill="#d9e6ee" stroke="${ink}" stroke-width="5"/>`).join("")}<rect x="910" y="600" width="100" height="160" fill="#4a3020" stroke="${ink}" stroke-width="6"/></g>${[160, 1560].map((x) => `<rect x="${x}" y="680" width="240" height="120" fill="#8a8a7a" stroke="${ink}" stroke-width="6"/><path d="M${x - 10} 690 Q${x + 120} 620 ${x + 250} 690" fill="#6a6a5a" stroke="${ink}" stroke-width="6"/>`).join("")}${sticker(960, 950, "BLETCHLEY PARK", { size: 60, rot: -2, bg: "#2f6b3a" })}<g id="pop-tur">${sticker(1500, 160, "AMONG THEM: ALAN TURING", { size: 40, rot: 2, bg: ink })}</g></g>`;
    const split = `<g id="cut-split" data-layout-allow-overlap="true"><rect width="960" height="1080" fill="#1f2a3a"/><rect y="760" width="960" height="320" fill="#2b3346"/>${Array.from({ length: 6 }, (_, i) => `<circle cx="${100 + i * 150}" cy="${200 + (i % 2) * 60}" r="30" fill="#c9a24a" stroke="${ink}" stroke-width="5"/>`).join("")}<rect x="120" y="360" width="60" height="400" fill="#555" stroke="${ink}" stroke-width="5"/><rect x="90" y="320" width="120" height="60" rx="10" fill="#444" stroke="${ink}" stroke-width="5"/>${place(CAST.uboat({ pose: "point" }), 520, 1060, 1.45, { id: "uboat" })}${sticker(300, 120, "U-BOAT, NORTH ATLANTIC", { size: 36, rot: -2, bg: ink })}` +
      `<rect x="960" width="960" height="1080" fill="#cbb995"/><rect x="960" y="780" width="960" height="300" fill="#7a5a3c"/>${H.window(1520, 140, 300, 240, "#a9c3d6")}<g transform="translate(1180 620)"><rect x="-150" y="-180" width="300" height="300" rx="10" fill="#6a6a6a" stroke="${ink}" stroke-width="7"/>${Array.from({ length: 9 }, (_, i) => `<circle cx="${-90 + (i % 3) * 90}" cy="${-120 + Math.floor(i / 3) * 80}" r="28" fill="#c9a24a" stroke="${ink}" stroke-width="5"/>`).join("")}</g>${H.table(1000, 800, 880, "#5b3d24")}<g id="pop-paper" transform="translate(1260 760) rotate(-4)"><rect x="-150" y="-36" width="300" height="72" fill="#fffaf0" stroke="${ink}" stroke-width="4"/><text y="12" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="28" fill="${ink}">GRID 42 · DAWN</text></g>${place(CAST.codebreakerUK({ pose: "hold", prop: `<g transform="translate(150 206)"><path d="M-22 -18 H22 L16 18 H-16Z" fill="#fff" stroke="${ink}" stroke-width="4"/><path d="M22 -10 q16 4 0 18" stroke="${ink}" stroke-width="4" fill="none"/></g>` }), 1640, 1060, 1.45, { id: "cbuk", flip: true })}${sticker(1290, 340, "MEANWHILE, IN ENGLAND", { size: 34, rot: 2, bg: "#2f6b3a" })}<path d="M960 0 V1080" stroke="${ink}" stroke-width="14"/></g>`;
    const cost = `<g id="fade-cost" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#151a24"/>${Array.from({ length: 12 }, (_, i) => `<g transform="translate(${260 + (i % 6) * 280} ${330 + Math.floor(i / 6) * 160})"><path d="M-90 0 L90 0 L70 40 L-80 40Z" fill="#6a6d72" stroke="#888" stroke-width="4"/><rect x="-40" y="-36" width="70" height="36" fill="#6a6d72" stroke="#888" stroke-width="4"/></g>`).join("")}<text x="960" y="180" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="52" fill="#e9e2cf">THOUSANDS OF ALLIED SHIPS SUNK</text>` +
      `<g id="fade-ub3"><text x="960" y="760" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="38" fill="#c9c2b0">U-BOAT CREWMEN WHO NEVER CAME HOME</text>${[0, 1, 2, 3].map((i) => `<rect x="${560 + i * 210}" y="800" width="180" height="160" rx="12" fill="${i < 3 ? "#3a3d44" : "#151a24"}" stroke="#c9c2b0" stroke-width="6"/>`).join("")}<text x="960" y="1040" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="#fffaf0">AROUND 3 IN 4</text></g></g>`;
    return H.defs() + map + house + split + cost + H.grain();
  };

  // F12 — The desert
  S["12"] = () => {
    const Af = "africa";
    const amap = (extra) => H.map(Af, { ly: "#4a6e3a", it: "#4a6e3a", eg: "#a08b5b", tn: "#c9b98a", dz: "#c9b98a", ma: "#c9b98a" }, { sea: "#2b4a6b", land: "#e2cf9a" }) + extra;
    const m1 = amap(H.arrow([[13.2, 32.2], [20, 31.6], [24, 31.7], [28.9, 30.9]], Af, { id: "arr-rom", col: "#6f7766", w: 26 }) + H.pin("El Alamein", Af, { dy: 50 }) + H.pin("Tobruk", Af, { dy: -26 }) + H.pin("Cairo", Af, { dy: 50 }));
    const m2 = amap(H.arrow([[29, 30.7], [24, 31.4], [18, 30.7], [12, 32.2], [10.4, 35.4]], Af, { id: "arr-mont", col: "#a08b5b", w: 26 }) +
      H.arrow([[-10.5, 34.6], [-7.6, 33.6]], Af, { id: "arr-t1", col: "#3d6fa3", w: 22 }) + H.arrow([[-4, 37.5], [-0.7, 35.8]], Af, { id: "arr-t2", col: "#3d6fa3", w: 22 }) + H.arrow([[1.5, 38.8], [3.1, 36.9]], Af, { id: "arr-t3", col: "#3d6fa3", w: 22 }) + H.arrow([[3.1, 36.4], [7, 36.5], [9.7, 36.6]], Af, { id: "arr-t4", col: "#3d6fa3", w: 22 }) +
      H.pin("El Alamein", Af, { dy: 50 }) + H.pin("Casablanca", Af, { dy: 50, size: 28 }) + H.pin("Algiers", Af, { dy: 50, size: 28 }) + H.pin("Tunis", Af, { dy: -26 }) + sticker(1500, 980, "AXIS OUT OF AFRICA: MAY 1943", { size: 42, rot: -2, bg: "#2f6b3a", id: "st-may" }));
    const balcony = g.Scenes["07b"]();
    return H.defs() + H.sky("#f2c38a", "#f9e6c4") + `<circle cx="1600" cy="200" r="90" fill="#ffd86a" stroke="${ink}" stroke-width="5"/><path d="M0 640 Q400 600 900 650 T1920 630 V1080 H0Z" fill="#e2c98a" stroke="${ink}" stroke-width="6"/><path d="M0 820 Q600 780 1200 830 T1920 820 V1080 H0Z" fill="#d6b877" opacity=".7"/>` +
      `<g id="tumbleweed" transform="translate(1100 820)"><circle r="40" fill="none" stroke="#8a6a3a" stroke-width="6"/><path d="M-30 -20 L30 20 M-30 20 L30 -20 M0 -40 V40" stroke="#8a6a3a" stroke-width="5"/></g>` +
      H.tank(1500, 760, 0.7, "", "#b09a68") +
      place(CAST.rommel({ pose: "point" }), 1250, 1060, 1.45, { id: "rommel", flip: true }) +
      `<g id="klausd">${place(CAST.klaus({ pose: "hold", brows: "worried", prop: `<g transform="translate(150 215)"><rect x="-30" y="-40" width="60" height="80" rx="8" fill="#5a6a3a" stroke="${ink}" stroke-width="5"/><path d="M-30 -10 L30 30 M30 -10 L-30 30" stroke="#4a5a2a" stroke-width="4"/></g>` }), 560, 1060, 1.4)}${P.gauge(860, 860, 1.0, 0.25, { id: "gauge" })}</g>` +
      `<g id="fade-m1" data-layout-allow-overlap="true">${m1}</g><g id="fade-m2" data-layout-allow-overlap="true">${m2}</g>` +
      `<g id="pip-mont"><circle cx="1720" cy="300" r="100" fill="#efe6d2" stroke="${ink}" stroke-width="8"/><clipPath id="pmc"><circle cx="1720" cy="300" r="94"/></clipPath><g clip-path="url(#pmc)">${place(CAST.montgomery({ pose: "hips" }), 1720, 515, 0.88)}</g>${sticker(1720, 412, "MONTGOMERY", { size: 26, rot: -2, bg: ink, pad: 14 })}</g>` +
      H.cut("cut-ban", balcony) + H.tp(2) + H.date(300, 110, "NORTH AFRICA, 1942", "st-date") + H.grain();
  };

  // Mussolini's balcony + Enzo's press (re-used by F12 and F21)
  S["07b"] = (banner = "") =>
    H.sky("#f2c38a", "#f8e2bd") +
    `<rect x="1040" y="0" width="880" height="760" fill="#e0b98a" stroke="${ink}" stroke-width="6"/><rect x="1180" y="120" width="560" height="380" rx="20" fill="#5a3b28" stroke="${ink}" stroke-width="6"/>` +
    `<g><rect x="1100" y="500" width="720" height="40" fill="#efd9b6" stroke="${ink}" stroke-width="6"/>${Array.from({ length: 9 }, (_, i) => `<rect x="${1120 + i * 80}" y="540" width="26" height="110" fill="#efd9b6" stroke="${ink}" stroke-width="4"/>`).join("")}<rect x="1100" y="650" width="720" height="34" fill="#efd9b6" stroke="${ink}" stroke-width="6"/></g>` +
    place(CAST.mussolini({ pose: "raise", mouth: "grin", brows: "happy" }), 1460, 510, 1.25, { id: "muss" }) +
    `<path d="M0 760 H1920 V1080 H0Z" fill="#c9b08a" stroke="${ink}" stroke-width="5"/>` +
    `<g id="press"><rect x="200" y="620" width="380" height="300" rx="12" fill="#6a6d72" stroke="${ink}" stroke-width="7"/><circle cx="300" cy="700" r="56" fill="#8a8d92" stroke="${ink}" stroke-width="6"/><circle cx="480" cy="700" r="56" fill="#8a8d92" stroke="${ink}" stroke-width="6"/><rect x="230" y="800" width="320" height="70" fill="#fffaf0" stroke="${ink}" stroke-width="5"/></g>` +
    place(CAST.enzo({ pose: "hold", brows: "smug", mouth: "flat" }), 760, 1040, 1.35, { id: "enzo", flip: true }) +
    `<g id="pop-blank">${P.banner(760, 320, 760, "", { size: 62 })}${sticker(1040, 410, "(FILL IN)", { size: 36, rot: 6, bg: "#c9a24a" })}</g>`;
  // F13 — Spam
  S["13"] = () => {
    const tins = Array.from({ length: 18 }, (_, i) => { const r = Math.floor(i / 6), c = i % 6; return `<g transform="translate(${1180 + c * 92 + r * 46} ${960 - r * 70})"><rect x="-40" y="-34" width="80" height="68" rx="10" fill="#3d6fa3" stroke="${ink}" stroke-width="5"/><rect x="-40" y="-10" width="80" height="22" fill="#e2b33c"/><text y="8" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="16" fill="${ink}">SPAM</text></g>`; }).join("");
    return H.defs() + H.sky("#b4c2cc", "#e3e9ed") + `<rect y="520" width="1920" height="200" fill="#4a6a8a"/><path d="M0 700 H1920 V1080 H0Z" fill="#8a8a86" stroke="${ink}" stroke-width="6"/>` +
      `<g><path d="M200 520 L1400 520 L1340 640 L260 640Z" fill="#5a6470" stroke="${ink}" stroke-width="8"/><rect x="900" y="380" width="180" height="140" fill="#6a7480" stroke="${ink}" stroke-width="7"/><text x="760" y="600" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="#fffaf0">LIBERTY SHIP · FROM USA</text></g>` +
      `<g><rect x="1500" y="180" width="30" height="520" fill="#c9a24a" stroke="${ink}" stroke-width="5"/><path d="M1515 200 L1100 260" stroke="#c9a24a" stroke-width="22"/><path d="M1515 200 L1100 260" stroke="${ink}" stroke-width="4" stroke-dasharray="10 10"/></g>` +
      `<g id="pop-trucks">${[260, 520].map((x) => `<g transform="translate(${x} 800)"><rect x="-110" y="-90" width="150" height="90" fill="#5f6a3e" stroke="${ink}" stroke-width="6"/><rect x="40" y="-60" width="70" height="60" fill="#6b7448" stroke="${ink}" stroke-width="6"/><circle cx="-60" cy="10" r="26" fill="#2c2e28" stroke="${ink}" stroke-width="5"/><circle cx="70" cy="10" r="26" fill="#2c2e28" stroke="${ink}" stroke-width="5"/></g>`).join("")}${sticker(400, 640, "TRUCKS: 100,000s", { size: 34, rot: -3, bg: ink })}</g>` +
      `<g id="pop-boots"><g transform="translate(800 900)">${[0, 1, 2].map((i) => `<path d="M${-70 + i * 60} ${-80 - i * 12} v60 h50 q20 0 20 20 h-70Z" fill="#5a3a22" stroke="${ink}" stroke-width="5"/>`).join("")}</g>${sticker(800, 760, "BOOTS: MILLIONS", { size: 34, rot: 2, bg: ink })}</g>` +
      `<g id="pop-tins">${tins}</g>` +
      place(CAST.aide({ pose: "hold", prop: `<g transform="translate(108 220)"><rect x="-26" y="-22" width="52" height="44" rx="8" fill="#3d6fa3" stroke="${ink}" stroke-width="4"/><rect x="-26" y="-6" width="52" height="14" fill="#e2b33c"/></g>` }), 1700, 1060, 1.35, { id: "aide", flip: true }) +
      place(CAST.stalin({ pose: "hold", brows: "neutral", mouth: "flat", prop: `<g transform="translate(108 218)"><rect x="-28" y="-24" width="56" height="48" rx="8" fill="#3d6fa3" stroke="${ink}" stroke-width="4"/><rect x="-28" y="-6" width="56" height="14" fill="#e2b33c"/></g>` }), 1080, 1060, 1.45, { id: "stalin" }) +
      `<g id="cut-memo" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#2a2620"/>${H.doc(960, 520, 900, 600, ["“Without Spam we wouldn’t", "have been able to feed", "our army.”", 0, "— Nikita Khrushchev"], { title: "KHRUSHCHEV REMEMBERS", rot: -2, size: 40 })}</g>` +
      H.date(330, 110, "SOVIET PORT, 1942", "st-date") + H.grain();
  };

  // F14 — Leningrad (straight)
  S["14"] = () => {
    const L = "ladoga";
    const lake = [[31.05, 59.93], [31.2, 60.13], [30.95, 60.35], [30.55, 60.6], [30.1, 60.95], [30.4, 61.25], [30.9, 61.45], [31.5, 61.7], [32.3, 61.75], [32.75, 61.45], [32.95, 61.0], [32.85, 60.6], [32.6, 60.35], [32.3, 60.15], [32.05, 60.0], [31.6, 59.92]];
    const ger = [[29.6, 59.86], [30.0, 59.78], [30.3, 59.76], [30.6, 59.8], [30.85, 59.88], [31.05, 59.93], [31.6, 59.9], [32.0, 59.95]];
    const fin = [[29.5, 60.18], [29.9, 60.25], [30.3, 60.3], [30.6, 60.45], [30.75, 60.55]];
    return H.defs() + H.map(L, { ussr: "#4a4f58", fi: "#42464f" }, { sea: "#0e131c", land: "#4a4f58" }) +
      `<path d="${Geo.poly(lake, L)}" fill="#1c2636" stroke="#5a6a80" stroke-width="4"/>` + H.line([[31.03, 59.94], [30.7, 59.85], [30.45, 59.88], [30.32, 59.94]], L, { col: "#1c2636", w: 14 }) +
      `<g id="fade-city">${H.pin("Leningrad", L, { size: 40, r: 16, dy: -34 })}</g>` +
      `<g id="arr-ger">${H.line(ger, L, { col: "#8a8f99", w: 16 })}</g><g id="arr-fin">${H.line(fin, L, { col: "#8a8f99", w: 16 })}</g>` +
      (() => { const a = Geo.project([30.1, 59.55], L), b = Geo.project([29.7, 60.45], L); return `<g id="fade-lines"><text x="${a[0].toFixed(0)}" y="${a[1].toFixed(0)}" text-anchor="middle" class="t-map" font-size="30">GERMAN LINES</text><text x="${b[0].toFixed(0)}" y="${b[1].toFixed(0)}" text-anchor="middle" class="t-map" font-size="30">FINNISH LINES</text></g>`; })() +
      `<g id="arr-road"><path d="${Geo.route([[31.25, 60.13], [31.6, 60.08], [32.03, 60.0]], L)}" stroke="#e9e2cf" stroke-width="10" fill="none" stroke-linecap="round"/></g>` +
      (() => { const [x, y] = Geo.project([31.65, 60.25], L); return `<g id="fade-road"><text x="${x.toFixed(0)}" y="${y.toFixed(0)}" text-anchor="middle" class="t-map" font-size="32">ROAD OF ICE · LAKE LADOGA</text></g>`; })() +
      `<g id="fade-days">${sticker(400, 110, "SIEGE: ALMOST 900 DAYS", { size: 44, rot: 0, bg: "#2a2c33" })}</g>` +
      `<g id="fade-card" transform="translate(1540 330) rotate(3)"><rect x="-230" y="-170" width="460" height="340" fill="#e9e2cf" stroke="#555" stroke-width="6"/><text y="-110" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="30" fill="${ink}">BREAD RATION CARD</text><path d="M-200 -86 H200" stroke="#555" stroke-width="3"/><text y="30" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="110" fill="${ink}">125 g</text><text y="110" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="30" fill="#555">per day · winter 1941</text></g>` +
      H.counter(1460, 930, "CIVILIANS DIED", "AROUND 800,000", "cnt-civ", 560) +
      H.vignette(0.6) + H.grain();
  };

  // F15 — The name: the wall map of the south
  S["15"] = () => {
    const So = "south";
    const inner = H.arrow([[36.2, 50], [38.5, 48.5], [43.5, 48.8]], So, { id: "arr-sta", col: "#6f7766", w: 26 }) + H.arrow([[38, 47.5], [39.8, 46], [40.1, 44.8]], So, { id: "arr-cau", col: "#6f7766", w: 26 }) +
      `<g id="pop-oil">${["Maikop", "Grozny"].map((n) => { const [x, y] = Geo.at(n, So); return `<g transform="translate(${x.toFixed(0)} ${y.toFixed(0)})"><path d="M-30 30 L0 -70 L30 30Z M-20 0 H20 M-14 -30 H14" fill="none" stroke="${ink}" stroke-width="7"/><circle cy="-80" r="14" fill="${ink}"/><text y="80" text-anchor="middle" class="t-map" font-size="44">OIL</text></g>`; }).join("")}</g>` +
      H.pin("Stalingrad", So, { size: 52, dy: -36, r: 16 }) + H.pin("Rostov", So, { dy: 54, size: 40 }) +
      `<g id="pop-ring">${(() => { const [x, y] = Geo.at("Stalingrad", So); return `<circle cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="110" fill="none" stroke="${K.red}" stroke-width="14"/>`; })()}</g>` +
      `<path d="${Geo.route([[49, 55], [48, 52], [46, 50], [44.6, 48.8], [46, 47.5], [47.9, 46.4]], So)}" stroke="#3d6fa3" stroke-width="14" fill="none"/>`;
    const wall = H.wallmap(So, { ussr: "#c98a7a" }, inner, { x: 160, y: 110, w: 1220, h: 690, sea: "#2b4a6b" });
    const city = `<rect width="1920" height="1080" fill="#c9d3dc"/><path d="M0 820 H1920 V1080 H0Z" fill="#3d6fa3"/>${Array.from({ length: 12 }, (_, i) => `<rect x="${i * 160}" y="${460 + (i % 3) * 60}" width="130" height="${360 - (i % 3) * 60}" fill="#8a8580" stroke="${ink}" stroke-width="5"/>${i % 3 === 0 ? `<rect x="${i * 160 + 80}" y="${300 + (i % 3) * 60}" width="34" height="170" fill="#6a6560" stroke="${ink}" stroke-width="4"/>` : ""}`).join("")}${H.label(960, 960, "THE VOLGA", 48)}<g transform="translate(960 220) rotate(-2)"><rect x="-460" y="-80" width="920" height="160" rx="16" fill="#fffaf0" stroke="${ink}" stroke-width="8"/><text y="34" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="100" fill="${ink}"><tspan fill="${K.red}">STALIN</tspan>GRAD</text></g>`;
    const split = `<rect width="960" height="1080" fill="#8a2a22"/><rect x="960" width="960" height="1080" fill="#4a4e44"/>${place(CAST.stalin({ pose: "point", brows: "angry", mouth: "frown" }), 480, 1100, 2.0)}${place(CAST.hitler({ pose: "point", brows: "furious", mouth: "shout" }), 1440, 1100, 2.0, { flip: true })}<path d="M960 0 L900 300 L1010 520 L930 800 L960 1080" stroke="#ffcc33" stroke-width="18" fill="none"/>`;
    return H.defs() + H.room("#8a7d68", "#5a4e3c") + wall +
      place(CAST.hitler({ pose: "point", mouth: "grin", brows: "smug" }), 1560, 1050, 1.45, { id: "hitler", flip: true }) +
      place(CAST.klaus({ pose: "armsUp", brows: "happy", mouth: "grin" }), 380, 1060, 1.3, { id: "klaus" }) +
      H.cut("cut-city", city) + H.cut("cut-split", split) +
      `<g id="pop-kmid">${place(CAST.klaus({ pose: "shrug", brows: "worried", mouth: "wobbly" }), 960, 1100, 1.25)}</g>` +
      H.date(1500, 110, "SUMMER 1942", "st-date") + H.grain();
  };

  // F16 — Room by room: the cross-section (centerpiece)
  S["16"] = () => {
    const sky = `<rect width="1920" height="1080" fill="#6a6d72"/>`;
    // ruined building cross-section: 4 floors, broken right edge, stairs in the middle
    const F = [220, 420, 620, 820];
    const bld = `<g id="bld"><path d="M240 980 V160 L420 120 L520 170 L700 110 L860 150 L1080 100 L1260 160 L1420 120 L1560 210 L1680 180 V980Z" fill="#b8ad9c" stroke="${ink}" stroke-width="10" stroke-linejoin="round"/>` +
      F.map((y) => `<rect x="240" y="${y + 170}" width="1440" height="30" fill="#8f8576" stroke="${ink}" stroke-width="5"/>`).join("") +
      [[400, 260], [1500, 300], [600, 700], [1300, 520]].map(([x, y]) => `<path d="M${x - 70} ${y - 60} l40 30 l-20 40 l60 10 l30 -50 l-20 -60Z" fill="#6a6d72" stroke="${ink}" stroke-width="5"/>`).join("") +
      // stairs between the two rooms on floor 3
      `<g id="stairs">${Array.from({ length: 7 }, (_, i) => `<rect x="${880 + i * 24}" y="${790 - i * 28}" width="${170 - i * 24}" height="28" fill="#a89a82" stroke="${ink}" stroke-width="4"/>`).join("")}<text x="960" y="560" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="#fffaf0" stroke="${ink}" stroke-width="8" paint-order="stroke">STAIRS</text></g>` +
      // kitchen (left) and bathroom (right), floor 3 (y 620..790)
      `<rect x="320" y="680" width="140" height="110" fill="#d9d4c8" stroke="${ink}" stroke-width="5"/><circle cx="360" cy="700" r="12" fill="${ink}"/><circle cx="420" cy="700" r="12" fill="${ink}"/><text x="390" y="660" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="#fffaf0" stroke="${ink}" stroke-width="7" paint-order="stroke">KITCHEN</text>` +
      `<path d="M1420 730 h220 v30 q0 30 -30 30 h-160 q-30 0 -30 -30Z" fill="#fff" stroke="${ink}" stroke-width="5"/><text x="1400" y="660" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="#fffaf0" stroke="${ink}" stroke-width="7" paint-order="stroke">BATHROOM</text>` +
      // other floors: soldiers in windows
      [[380, 390, "de"], [1520, 390, "su"], [420, 990, "de"], [1460, 990, "su"]].map(([x, y, s]) => place((s === "de" ? CAST.soldierDE : CAST.soldierSU)({ pose: "hold", brows: "angry" }), x, y - 5, 0.55, { flip: s === "su" })).join("") + `</g>`;
    const ger = place(CAST.soldierDE({ pose: "armsUp", mouth: "grin", brows: "happy" }), 640, 990 - 180, 0.62, { id: "gsol" });
    const sov = place(CAST.soldierSU({ pose: "armsUp", mouth: "grin", brows: "happy" }), 1240, 990 - 180, 0.62, { id: "ssol", flip: true });
    const bomb = `<g id="fade-bomb" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#7a5a4a"/>${Array.from({ length: 14 }, (_, i) => `<rect x="${i * 140}" y="${600 + (i % 4) * 50}" width="120" height="${480 - (i % 4) * 50}" fill="#5a4a40" stroke="${ink}" stroke-width="5"/>`).join("")}<g id="fires">${[150, 460, 760, 1100, 1400, 1700].map((x, i) => `<g>${H.smoke(x, 620 + (i % 3) * 40, 1.1)}${H.fire(x, 640 + (i % 3) * 40, 1.1)}</g>`).join("")}</g>${[[300, 150], [800, 110], [1300, 170], [1700, 120]].map(([x, y]) => H.bomber(x, y, 0.6, "#5d5a45")).join("")}${sticker(400, 1000, "STALINGRAD, AUGUST 1942", { size: 44, rot: -2, bg: ink })}</g>`;
    // schematic: the Volga at night, the city on the west bank, a thin Soviet strip, boats crossing
    const strip = `<g id="fade-strip" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#1c2230"/><path d="M1180 -20 C1120 300 1300 600 1240 1100 L1920 1100 L1920 -20Z" fill="#1d3450"/><path d="M0 0 H1180 C1120 300 1300 600 1240 1080 H0Z" fill="#3a3d44"/>` +
      Array.from({ length: 40 }, (_, i) => `<rect x="${60 + (i % 8) * 130}" y="${80 + Math.floor(i / 8) * 190}" width="90" height="120" fill="#4a4e56" stroke="#2a2c33" stroke-width="4"/>`).join("") +
      `<path d="M1090 -20 C1030 300 1210 600 1150 1100 L1240 1100 C1300 600 1120 300 1180 -20Z" fill="${K.red}" opacity=".9"/><text x="560" y="560" text-anchor="middle" class="t-map" font-size="56">GERMAN-HELD</text><text x="1560" y="300" text-anchor="middle" class="t-map" font-size="48">THE VOLGA</text>` +
      [[1700, 420], [1640, 620], [1720, 820]].map(([x, y], i) => `<g id="pop-boat${i}" transform="translate(${x} ${y})"><path d="M-70 0 H70 L50 30 H-50Z" fill="#6b4a2c" stroke="${ink}" stroke-width="5"/>${[-40, 0, 40].map((dx) => `<circle cx="${dx}" cy="-14" r="14" fill="#9a8f62" stroke="${ink}" stroke-width="3"/>`).join("")}<path d="M-90 10 L-200 10" stroke="#fffaf0" stroke-width="6" stroke-dasharray="14 10"/></g>`).join("") +
      [[1500, 380], [1420, 700]].map(([x, y]) => `<g transform="translate(${x} ${y})"><circle r="40" fill="#ffd23f" opacity=".7"/><circle r="18" fill="#fff"/></g>`).join("") +
      `${sticker(1000, 140, "THE SOVIET STRIP", { size: 40, rot: -2, bg: K.red })}${sticker(1560, 1000, "FERRIED IN EVERY NIGHT", { size: 40, rot: 2, bg: ink })}</g>`;
    const chui = `<g id="cut-chui" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#4a3f33"/><path d="M0 200 Q960 80 1920 200" stroke="#2e261e" stroke-width="40" fill="none"/>${Array.from({ length: 6 }, (_, i) => `<rect x="${i * 340}" y="120" width="40" height="760" fill="#5a4a38" stroke="${ink}" stroke-width="5"/>`).join("")}<rect y="840" width="1920" height="240" fill="#3a3028" stroke="${ink}" stroke-width="5"/>${H.table(760, 760, 420, "#5a4028")}${place(CAST.chuikov({ pose: "point" }), 560, 1060, 1.5, { id: "chui" })}${place(CAST.soldierSU({ pose: "shrug", brows: "surprised", mouth: "open" }), 1380, 1060, 1.4, { id: "ssol2", flip: true })}<g id="st-chui">${sticker(560, 300, "VASILY CHUIKOV", { size: 42, rot: -3, bg: K.red })}</g></g>`;
    const air = `<g id="cut-air" data-layout-allow-overlap="true">${H.sky("#8a9aa8", "#c9d3dc")}<path d="M0 760 H1920 V1080 H0Z" fill="#7a6a5a" stroke="${ink}" stroke-width="5"/><path d="M780 770 h140 M1000 770 h140" stroke="#4a3a2a" stroke-width="30"/>${Array.from({ length: 5 }, (_, i) => place(CAST.soldierDE({ pose: "hold" }), 520 + i * 70, 830, 0.42)).join("")}${Array.from({ length: 5 }, (_, i) => place(CAST.soldierSU({ pose: "hold" }), 1120 + i * 70, 830, 0.42, { flip: true })).join("")}<g transform="translate(960 900)"><path d="M-120 0 H120" stroke="#ffcc33" stroke-width="6" stroke-dasharray="14 10"/><text y="60" text-anchor="middle" class="t-map" font-size="34">A GRENADE-THROW</text></g><g id="circle-pl">${H.plane(960, 260, 0.9, "#6f7766")}</g>` +
      `<g id="pip-gp"><circle cx="1680" cy="280" r="120" fill="#efe6d2" stroke="${ink}" stroke-width="8"/><clipPath id="gpc"><circle cx="1680" cy="280" r="112"/></clipPath><g clip-path="url(#gpc)">${place(CAST.pilotDE({ pose: "shrug", brows: "worried", mouth: "open" }), 1680, 540, 1.05)}</g></g></g>`;
    const months = `<g id="cut-months" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#5a5048"/>${["SEPT", "OCT", "NOV"].map((m, i) => `<g id="pop-m${i}">${H.calendar(560 + i * 400, 520, "1942", m, { s: 1.2, col: "#7a2a22" })}</g>`).join("")}</g>`;
    return H.defs() + sky + bld + ger + sov + bomb + strip + chui + air + months + H.date(300, 110, "STALINGRAD, AUTUMN 1942", "st-date") + H.vignette(0.4) + H.grain();
  };

  // F17 — "Mostly": the Munich beer hall speech
  S["17"] = () => {
    const pockets = `<g id="pop-inset" transform="translate(1500 330)"><rect x="-300" y="-220" width="600" height="440" rx="12" fill="#e2d6b4" stroke="${ink}" stroke-width="8"/><text y="-170" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="${ink}">"SMALL POCKETS"</text><rect x="-260" y="-140" width="520" height="340" fill="#b8ad9c" stroke="${ink}" stroke-width="4"/><path d="M180 -140 Q140 20 200 200" stroke="#3d6fa3" stroke-width="40" fill="none"/>` +
      `<g id="pop-p1"><path d="M150 -140 Q110 20 170 200" stroke="${K.red}" stroke-width="22" fill="none"/></g>` +
      `<g id="pop-p2"><path d="M-20 -110 h170 v150 h-180Z" fill="${K.red}" opacity=".8" stroke="${ink}" stroke-width="4"/><text x="60" y="-30" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="24" fill="#fff">FACTORIES</text></g>` +
      `<g id="pop-p3"><path d="M-300 -230 H300 V230 H-300Z" fill="${K.red}" opacity=".85"/><text y="30" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="56" fill="#fffaf0">THE SOVIET ARMY</text></g></g>`;
    return H.defs() + H.room("#a77a4a", "#6e4b2c") + `<g>${Array.from({ length: 8 }, (_, i) => `<path d="M${i * 280} 0 V820" stroke="#7d5632" stroke-width="20"/>`).join("")}<path d="M0 120 H1920" stroke="#5a3b20" stroke-width="30"/></g>` +
      H.flagDE(120, 160, 1) + H.flagDE(1650, 160, 1) +
      `<rect x="760" y="640" width="400" height="300" fill="#6b4a2c" stroke="${ink}" stroke-width="8"/>` + place(CAST.hitler({ pose: "pointUp", mouth: "shout", brows: "furious" }), 960, 700, 1.3, { id: "hitler" }) +
      `<g id="crowd">${Array.from({ length: 10 }, (_, i) => place(CAST.civilian({ pose: i % 2 ? "armsUp" : "raise", mouth: "grin", capCol: ["#5a5048", "#6a4a3a", "#4a5a4a"][i % 3] }), 90 + i * 190, 1140, 1.0, { flip: i % 2 === 0 })).join("")}</g>` +
      `<g id="klaus">${place(CAST.klaus({ pose: "hold", brows: "worried", mouth: "flat" }), 380, 900, 1.25)}${H.phone(560, 760, 0.8)}</g>` + pockets +
      H.date(300, 110, "MUNICH, 8 NOV 1942", "st-date") + H.grain();
  };

  // F18 — The trap: the ring closes
  S["18"] = () => {
    const St = "stalingrad";
    const map = H.mapX(St, { ussr: "#c9b98a" }, { sea: "#2b4a6b", extra: [{ pts: [[41.5, 49.6], [43.2, 49.5], [44.4, 49.2], [44.5, 48.6], [44.6, 48.1], [43.5, 47.6], [42.5, 47.9], [42, 48.6]], fill: "#6f7766", op: 0.85 }, { id: "fade-rom1", pts: [[39.6, 49.9], [41.6, 49.75], [42.6, 49.5], [42.4, 49.2], [41.4, 49.4], [39.6, 49.55]], fill: "#c9a24a", op: 0.95 }, { id: "fade-rom2", pts: [[44.4, 48.1], [44.7, 47.6], [44.4, 46.9], [43.9, 46.9], [44.0, 47.6]], fill: "#c9a24a", op: 0.95 }] }) +
      `<path d="${Geo.route([[44.3, 49.6], [44.45, 48.95], [44.55, 48.75], [44.65, 48.55], [45.1, 48.1], [45.6, 47.6]], St)}" stroke="#3d6fa3" stroke-width="30" fill="none"/>` +
      (() => { const a = Geo.project([40.6, 49.95], St), b = Geo.project([44.9, 47.3], St); return `<text x="${a[0].toFixed(0)}" y="${a[1].toFixed(0)}" text-anchor="middle" class="t-map" font-size="30">ROMANIAN 3rd ARMY</text><text x="${b[0].toFixed(0)}" y="${b[1].toFixed(0)}" text-anchor="middle" class="t-map" font-size="30">ROMANIAN 4th ARMY</text>`; })() +
      H.arrow([[41.2, 50.4], [42, 49.6], [42.9, 49.1], [43.45, 48.75]], St, { id: "arr-n", col: K.red, w: 30 }) + H.arrow([[44.9, 47.2], [44.1, 47.6], [43.8, 48.2], [43.6, 48.6]], St, { id: "arr-s", col: K.red, w: 30 }) +
      `<g id="pop-ring">${(() => { const [x, y] = Geo.project([43.6, 48.75], St); return `<ellipse cx="${(x + 40).toFixed(0)}" cy="${y.toFixed(0)}" rx="420" ry="290" fill="none" stroke="${K.red}" stroke-width="24" stroke-dasharray="40 20"/>`; })()}</g>` +
      H.pin("Stalingrad", St, { size: 40, dy: -30, r: 14 }) + H.pin("Kalach", St, { size: 32, dy: 54 }) +
      H.counter(1500, 960, "AXIS SOLDIERS TRAPPED", "ABOUT 300,000", "cnt-trap", 560) + sticker(420, 980, "NOVEMBER 1942", { size: 44, rot: -2, bg: ink, id: "st-date" });
    const hq = `<rect width="1920" height="1080" fill="#a89a82"/><rect y="820" width="1920" height="260" fill="#6b5a42" stroke="${ink}" stroke-width="5"/>` +
      place(CAST.hitler({ pose: "hips", mouth: "grin", brows: "smug" }), 520, 1040, 1.45, { id: "hitler" }) + place(CAST.klaus({ pose: "hold", brows: "worried", prop: P.clipboard(110, 222, 0.9) }), 1420, 1040, 1.4, { id: "klaus", flip: true }) +
      `<g id="pop-gor" transform="translate(960 230) rotate(-3)"><rect x="-260" y="-70" width="520" height="140" fill="#fbf6e8" stroke="${ink}" stroke-width="6"/><text y="-10" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="36" fill="${ink}">GÖRING'S PROMISE</text><text y="44" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="30" fill="${K.red}">(DUNKIRK, 1940)</text></g>` +
      `<g id="pop-chart" transform="translate(960 560)"><rect x="-330" y="-330" width="660" height="440" rx="12" fill="#fffaf0" stroke="${ink}" stroke-width="7"/><text y="-280" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="32" fill="${ink}">SUPPLIES PER DAY</text><rect x="-230" y="-230" width="160" height="300" fill="#6f7766" stroke="${ink}" stroke-width="5"/><text x="-150" y="-245" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="30" fill="${ink}">~750 t</text><text x="-150" y="104" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="26" fill="#555">NEEDED</text><g id="pop-bar100"><rect x="70" y="30" width="160" height="40" fill="${K.red}" stroke="${ink}" stroke-width="5"/><text x="150" y="16" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="30" fill="${ink}">~100 t</text><text x="150" y="104" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="26" fill="#555">DELIVERED</text></g><path d="M-330 70 H330" stroke="${ink}" stroke-width="5"/></g>` +
      `<g id="pop-17"><g transform="translate(1180 330) rotate(8)"><circle r="80" fill="${K.red}" stroke="${ink}" stroke-width="6"/><text y="20" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="60" fill="#fff">1/7</text></g></g>`;
    const winter = `<g id="fade-win" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#dfe6ec"/><path d="M0 700 Q960 660 1920 700 V1080 H0Z" fill="#f4f7fb" stroke="${ink}" stroke-width="5"/>${Array.from({ length: 6 }, (_, i) => place(CAST.soldierDE({ pose: "cross", brows: "sad", mouth: "flat" }), 260 + i * 280, 960, 1.0, { flip: i % 2 === 1 })).join("")}${Array.from({ length: 60 }, (_, i) => `<circle class="flake" cx="${(i * 131) % 1920}" cy="${(i * 71) % 900}" r="${4 + (i % 3) * 2}" fill="#fff"/>`).join("")}${P.stamp(960, 260, 1.4, "BREAKOUT FORBIDDEN", K.red, { rot: -6 })}</g>`;
    return H.defs() + map + H.cut("cut-hq", hq) + winter + H.grain();
  };

  // F19 — The promotion
  S["19"] = () => {
    const hq = H.room("#a89a82", "#6b5a42") + H.table(640, 760, 640, "#5b3d24") + P.radio(1180, 700, 0.7) +
      `<g id="pop-baton" transform="translate(860 720)"><rect x="-120" y="-50" width="240" height="60" rx="8" fill="#7a2a22" stroke="${ink}" stroke-width="5"/><rect x="-100" y="-38" width="200" height="22" rx="10" fill="#e2b33c" stroke="${ink}" stroke-width="4"/><text y="-70" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="30" fill="${ink}">FIELD MARSHAL</text></g>` +
      place(CAST.hitler({ pose: "point", mouth: "grin", brows: "smug" }), 420, 1040, 1.45, { id: "hitler" }) + place(CAST.klaus({ pose: "shrug", brows: "worried" }), 1560, 1040, 1.4, { id: "klaus", flip: true }) +
      `<g id="pop-list" transform="translate(1500 330) rotate(3)"><rect x="-220" y="-150" width="440" height="300" fill="#fbf6e8" stroke="${ink}" stroke-width="6"/>${["FOOD", "AMMUNITION", "ARMY"].map((w, i) => `<g id="pop-l${i}"><text x="-160" y="${-70 + i * 80}" font-family="Fredoka" font-weight="700" font-size="44" fill="${ink}">${w}</text><path d="M-170 ${-84 + i * 80} H${-160 + w.length * 30}" stroke="${K.red}" stroke-width="8"/></g>`).join("")}</g>`;
    const cellar = `<rect width="1920" height="1080" fill="#d9e0e6"/><rect y="760" width="1920" height="320" fill="#f4f7fb" stroke="${ink}" stroke-width="5"/><rect x="200" y="200" width="1100" height="560" fill="#8a8072" stroke="${ink}" stroke-width="8"/><path d="M200 200 L380 140 L560 200 L800 120 L1000 200 L1300 160 V200" fill="#8a8072" stroke="${ink}" stroke-width="6"/><rect x="620" y="480" width="260" height="280" fill="#2a2420" stroke="${ink}" stroke-width="8"/><text x="750" y="440" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="32" fill="${ink}">UNIVERMAG</text>` +
      [1350, 1550, 1750].map((x) => place(CAST.soldierSU({ pose: "hold", brows: "neutral", cap: "flat", capCol: "#7a6a4a" }), x, 1000, 1.2, { flip: true })).join("") +
      `<g id="paulus">${place(CAST.paulus({ pose: "armsUp" }), 750, 1000, 1.2)}</g>` + sticker(400, 110, "STALINGRAD, 31 JAN 1943", { size: 42, rot: -2, bg: ink });
    const end = `<g id="fade-end" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#cfd8e0"/><path d="M0 640 Q960 600 1920 640 V1080 H0Z" fill="#eef2f6" stroke="${ink}" stroke-width="5"/>${Array.from({ length: 10 }, (_, i) => `<rect x="${i * 200}" y="${300 + (i % 3) * 60}" width="160" height="${340 - (i % 3) * 60}" fill="#7a746c" stroke="${ink}" stroke-width="5"/><path d="M${i * 200} ${300 + (i % 3) * 60} l40 -40 l40 30 l40 -50 l40 60" fill="#7a746c" stroke="${ink}" stroke-width="5"/>`).join("")}<g id="column">${Array.from({ length: 14 }, (_, i) => place(CAST.soldierDE({ pose: "cross", brows: "sad", mouth: "flat", cap: "side", capY: -8 }), 60 + i * 120, 900 + (i % 2) * 30, 0.6)).join("")}</g>${sticker(400, 110, "2 FEBRUARY 1943", { size: 46, rot: -2, bg: ink })}` +
      H.counter(500, 300, "WENT INTO SOVIET CAPTIVITY", "ABOUT 90,000", "cnt-pow", 580) + H.counter(1420, 300, "EVER CAME HOME", "AROUND 5,000", "cnt-home", 480) +
      H.counter(960, 540, "DEAD, WOUNDED AND CAPTURED, BOTH SIDES", "CLOSE TO 2,000,000", "cnt-2m", 760) + `</g>`;
    return H.defs() + hq + H.cut("cut-cellar", cellar) + end + H.date(300, 110, "JANUARY 1943", "st-date") + H.tp(3) + H.grain();
  };

  // F20 — Kursk
  S["20"] = () => {
    const E = "east";
    const kmap = `<g id="fade-km" data-layout-allow-overlap="true">${H.mapX(E, { ussr: SU, de: AX, pl: AX, baltic: AX }, { extra: [{ pts: [[22, 56], [29, 58], [32, 55.5], [34.5, 53.4], [36.0, 53.2], [35.5, 52.0], [34.8, 51.6], [36.2, 50.8], [37.2, 50.3], [38.5, 49], [38.5, 47.2], [35, 46.5], [30, 46], [26, 48], [23.5, 51]], fill: AX }] })}${H.arrow([[36.0, 53.6], [36.2, 52.6]], E, { id: "arr-kn", col: "#6f7766", w: 22 })}${H.arrow([[36.6, 50.1], [36.4, 51.0]], E, { id: "arr-ks", col: "#6f7766", w: 22 })}${H.pin("Kursk", E, { dx: 90, size: 40 })}${H.pin("Moscow", E)}${sticker(560, 980, "JULY 1943", { size: 48, rot: -2, bg: ink })}</g>`;
    const steppe = H.sky("#c9d8a8", "#eef2d8") + `<path d="M0 480 H1920 V1080 H0Z" fill="#a8b46a" stroke="${ink}" stroke-width="5"/>` +
      Array.from({ length: 5 }, (_, i) => `<g id="pop-belt${i}">${`<path d="M0 ${540 + i * 100} H1920" stroke="#6a5a3a" stroke-width="${18 - i * 2}" stroke-dasharray="8 0"/>`}${Array.from({ length: 16 }, (_, j) => `<circle cx="${60 + j * 120 + (i % 2) * 60}" cy="${520 + i * 100}" r="9" fill="#3a3a3a" stroke="${ink}" stroke-width="3"/>`).join("")}</g>`).join("") +
      H.tank(300, 1000, 0.5, "", "#7a7a6a") + H.tank(700, 1040, 0.45, "", "#7a7a6a") + `<g id="pop-sutanks">${Array.from({ length: 7 }, (_, i) => H.tank(1060 + (i % 4) * 230, 500 + Math.floor(i / 4) * 60, 0.22, "", "#5d6b45", true)).join("")}</g>` + sticker(1300, 160, "BELT AFTER BELT OF MINEFIELDS", { size: 40, rot: 2, bg: ink });
    const tent = `<g id="cut-tent" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#9a8a62"/><path d="M0 0 L960 -80 L1920 0 V200 Q960 120 0 200Z" fill="#7a6a48" stroke="${ink}" stroke-width="6"/><rect y="820" width="1920" height="260" fill="#7a6a4a" stroke="${ink}" stroke-width="5"/>${place(CAST.hitler({ pose: "point", mouth: "shout", brows: "furious" }), 560, 1040, 1.45, { id: "hitler" })}${place(CAST.klaus({ pose: "hold", brows: "worried", prop: P.clipboard(110, 222, 0.9) }), 1380, 1040, 1.4, { id: "klaus", flip: true })}<g id="pop-more">${Array.from({ length: 8 }, (_, i) => H.tank(900 + (i % 4) * 140, 380 + Math.floor(i / 4) * 90, 0.18, "", "#5d6b45")).join("")}<text x="1110" y="300" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="34" fill="#fffaf0" stroke="${ink}" stroke-width="8" paint-order="stroke">SOVIET TANKS</text></g></g>`;
    const shop = `<g id="cut-repair" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#7a7468"/><rect y="840" width="1920" height="240" fill="#4a463e" stroke="${ink}" stroke-width="5"/><g transform="translate(960 180) rotate(-1)"><rect x="-380" y="-60" width="760" height="120" rx="12" fill="#2a2a2e" stroke="${ink}" stroke-width="7"/><text y="22" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="60" fill="#ffcc33">REPAIR SHOP</text></g>${H.tank(760, 760, 1.0, "", "#8a8a7a")}<rect x="560" y="800" width="60" height="60" fill="#c9a24a" stroke="${ink}" stroke-width="5"/><rect x="900" y="800" width="60" height="60" fill="#c9a24a" stroke="${ink}" stroke-width="5"/><g transform="translate(560 860) rotate(-70)"><rect x="-90" y="-40" width="180" height="80" rx="36" fill="#2c2e28" stroke="${ink}" stroke-width="6"/></g>${place(CAST.mechanic({ pose: "shrug" }), 1420, 1060, 1.4, { flip: true })}${place(CAST.mechanic({ pose: "hold", brows: "sad" }), 1700, 1060, 1.3, { flip: true })}</g>`;
    const back = `<g id="fade-back" data-layout-allow-overlap="true">${H.map(E, { ussr: SU, de: AX, pl: AX, baltic: AX, ro: "#6a6a5a" })}${[[[37, 53.5], [33.5, 53.6]], [[37, 51.5], [32.5, 51.2]], [[38.5, 49.5], [34, 49.3]], [[39, 47.4], [34.5, 47.2]]].map((p, i) => H.arrow(p, E, { id: `arr-w${i}`, col: K.red, w: 26 })).join("")}${H.pin("Kursk", E, { dx: 70, size: 34 })}${H.pin("Kiev", E)}</g>`;
    return H.defs() + steppe + kmap + tent + shop + back + H.grain();
  };

  // F21 — Enzo gets fired
  S["21"] = () => {
    const M = "med";
    const sicily = H.map(M, { it: "#2f6b3a", tn: "#a08b5b", ly: "#a08b5b", gr: AX, yu: AX, al: AX }, { sea: "#2b4a6b" }) + H.arrow([[11.5, 35.2], [13.4, 36.4], [14.4, 36.9]], M, { id: "arr-si1", col: "#3d6fa3", w: 24 }) + H.arrow([[16.5, 35.0], [15.6, 36.0], [15.2, 36.75]], M, { id: "arr-si2", col: "#a08b5b", w: 24 }) + H.pin("Rome", M) + H.pin("Syracuse", M, { dx: 110, dy: 10, size: 28 }) + sticker(500, 980, "SICILY, JULY 1943", { size: 48, rot: -2, bg: ink });
    const press = g.Scenes["07b"]().replace(/<g id="pop-blank">[\s\S]*$/, "").replace(place(CAST.mussolini({ pose: "raise", mouth: "grin", brows: "happy" }), 1460, 510, 1.25, { id: "muss" }), "").replace(place(CAST.enzo({ pose: "hold", brows: "smug", mouth: "flat" }), 760, 1040, 1.35, { id: "enzo", flip: true }), "");
    const box = `<g transform="translate(110 222)"><rect x="-40" y="-30" width="80" height="60" fill="#c99a5a" stroke="${ink}" stroke-width="4"/></g>`;
    const pip = (id, extra = "") => `<g id="${id}"><circle cx="1500" cy="300" r="130" fill="#efe6d2" stroke="${ink}" stroke-width="8"/><clipPath id="${id}-c"><circle cx="1500" cy="300" r="122"/></clipPath><g clip-path="url(#${id}-c)">${extra}${place(CAST.mussolini({ pose: "raise", mouth: "shout", brows: "angry" }), 1500, 540, 1.12)}</g></g>`;
    const glider = `<g id="fade-glider" data-layout-allow-overlap="true">${H.sky("#9fc6e2", "#e3f0f8")}${Toon.P.mountain(500, 1000, 1100, 700)}${Toon.P.mountain(1500, 1000, 1000, 560)}<rect x="380" y="270" width="260" height="90" fill="#efe0c0" stroke="${ink}" stroke-width="6"/><text x="510" y="250" text-anchor="middle" class="t-map" font-size="32">HOTEL, GRAN SASSO</text>${[[1300, 220], [1600, 330]].map(([x, y]) => `<g transform="translate(${x} ${y}) rotate(-12)"><path d="M-160 0 C-100 -20 100 -20 160 0 C100 14 -100 14 -160 0Z" fill="#8a8f7a" stroke="${ink}" stroke-width="6"/><path d="M-30 -4 L-80 -90 L-50 -90 L10 -4Z M-30 4 L-80 90 L-50 90 L10 4Z" fill="#8a8f7a" stroke="${ink}" stroke-width="5"/></g>`).join("")}${sticker(960, 980, "SEPTEMBER 1943", { size: 46, rot: -2, bg: ink })}</g>`;
    const puppet = `<g id="cut-puppet" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#2a2620"/><rect x="560" y="0" width="800" height="120" fill="#3a3d44" stroke="${ink}" stroke-width="6"/><text x="960" y="80" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="44" fill="#c9c2b0">MADE IN GERMANY</text>${[860, 960, 1060].map((x) => `<path d="M${x} 120 V${x === 960 ? 620 : 760}" stroke="#ddd" stroke-width="3"/>`).join("")}${place(CAST.mussolini({ pose: "shrug", mouth: "flat", brows: "worried" }), 960, 1040, 1.5)}${sticker(960, 220, "PUPPET STATE, NORTHERN ITALY", { size: 40, rot: -1, bg: K.red })}</g>`;
    return H.defs() + press + place(CAST.enzo({ pose: "hold", brows: "sad", mouth: "flat", prop: box }), 900, 1040, 1.35, { id: "enzo", flip: true }) + pip("pop-mp1") +
      `<g id="cut-map" data-layout-allow-overlap="true">${sicily}</g>` +
      `<g id="cut-bal" data-layout-allow-overlap="true">${H.sky("#f2c38a", "#f8e2bd")}<rect x="520" y="0" width="880" height="760" fill="#e0b98a" stroke="${ink}" stroke-width="6"/><rect x="660" y="120" width="560" height="380" rx="20" fill="#5a3b28" stroke="${ink}" stroke-width="6"/><rect x="580" y="500" width="720" height="180" fill="#efd9b6" stroke="${ink}" stroke-width="6"/><path d="M0 760 H1920 V1080 H0Z" fill="#c9b08a" stroke="${ink}" stroke-width="5"/>${place(CAST.guard({ pose: "hips" }), 400, 1040, 1.3)}${place(CAST.guard({ pose: "hips" }), 1520, 1040, 1.3, { flip: true })}<g id="st-arr">${P.stamp(960, 420, 1.4, "ARRESTED", K.red, { rot: -8 })}</g>${sticker(960, 900, "THE BALCONY: EMPTY", { size: 44, rot: -2, bg: ink })}</g>` +
      glider + puppet + `<g id="pop-mp2"><circle cx="1500" cy="300" r="130" fill="#efe6d2" stroke="${ink}" stroke-width="8"/><clipPath id="mp2c"><circle cx="1500" cy="300" r="122"/></clipPath><g clip-path="url(#mp2c)">${place(CAST.mussolini({ pose: "shrug", mouth: "flat", brows: "worried" }), 1500, 540, 1.12)}</g></g>` +
      `<g id="pop-unpack">${place(CAST.enzo({ pose: "hold", brows: "sad", mouth: "wobbly", prop: box }), 900, 1040, 1.35, { flip: true })}</g>` + H.grain();
  };

  // F22 — The firestorm (straight)
  S["22"] = () => {
    const Wv = "west";
    const map = H.map(Wv, { de: "#3a3d44", uk: "#4a4f58", fr: "#33363d", benl: "#33363d", dk: "#33363d" }, { sea: "#0e131c", land: "#2a2e36" }) +
      `<g id="fade-night">${[[[0.5, 52.6], [6, 52.6], [9.9, 53.5]], [[0.5, 51.6], [5, 51.2], [6.9, 50.9]], [[0.3, 51.0], [5.5, 50.2], [8.6, 50.1]]].map((p) => `<path d="${Geo.route(p, Wv)}" stroke="#8a9ac0" stroke-width="10" fill="none" stroke-dasharray="4 18" stroke-linecap="round"/>`).join("")}${sticker(500, 160, "BRITISH: BY NIGHT", { size: 40, rot: -2, bg: "#2a2c33" })}</g>` +
      `<g id="fade-day">${[[[0.8, 52.1], [7, 52.4], [11.6, 52.3]], [[0.8, 50.6], [6, 49.8], [11, 49.4]]].map((p) => `<path d="${Geo.route(p, Wv)}" stroke="#e9e2cf" stroke-width="10" fill="none" stroke-dasharray="4 18" stroke-linecap="round"/>`).join("")}${sticker(1500, 980, "AMERICANS: BY DAY", { size: 40, rot: 2, bg: "#2a2c33" })}</g>` +
      H.pin("Hamburg", Wv, { col: "#ffcf5a", size: 30, dx: 60 });
    // Hamburg schematic: the Elbe, the Alster, districts that burn
    const ham = `<g id="fade-ham" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#14161c"/>${Array.from({ length: 22 }, (_, i) => `<path d="M${i * 90} 0 V1080" stroke="#22252e" stroke-width="3"/>`).join("")}${Array.from({ length: 12 }, (_, i) => `<path d="M0 ${i * 90} H1920" stroke="#22252e" stroke-width="3"/>`).join("")}` +
      `<path d="M0 780 C400 720 800 820 1200 760 S1700 700 1920 740 L1920 860 C1700 820 1300 880 1000 860 S400 860 0 900Z" fill="#1c2636" stroke="#5a6a80" stroke-width="4"/><path d="M820 360 C860 300 940 300 960 380 C980 460 900 520 860 480 C820 440 800 420 820 360Z" fill="#1c2636" stroke="#5a6a80" stroke-width="4"/>` +
      `<text x="1500" y="830" text-anchor="middle" class="t-map" font-size="34">ELBE</text><text x="880" y="300" text-anchor="middle" class="t-map" font-size="28">ALSTER</text>` +
      [[1080, 520, 260, 180, "HAMMERBROOK"], [1360, 480, 260, 200, "HAMM"], [1160, 300, 240, 160, "BORGFELDE"], [1460, 260, 240, 180, "ROTHENBURGSORT"]].map(([x, y, w, h, n], i) => `<g id="pop-d${i}"><rect x="${x - w / 2}" y="${y - h / 2}" width="${w}" height="${h}" rx="18" fill="#d4501f" opacity=".85"/><rect x="${x - w / 2 + 20}" y="${y - h / 2 + 20}" width="${w - 40}" height="${h - 40}" rx="12" fill="#ffb03a" opacity=".6"/><text x="${x}" y="${y + 10}" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="${n.length > 10 ? 22 : 26}" fill="#fffaf0">${n}</text></g>`).join("") +
      sticker(420, 120, "HAMBURG, JULY 1943", { size: 46, rot: 0, bg: "#2a2c33" }) + H.counter(480, 960, "KILLED IN ONE WEEK", "AROUND 37,000", "cnt-ham", 520) + `</g>`;
    const crews = `<g id="fade-crews" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#101218"/>${Array.from({ length: 30 }, (_, i) => H.bomber(200 + (i % 10) * 170, 200 + Math.floor(i / 10) * 150, 0.42, "#4a4d55")).join("")}` + H.counter(960, 800, "BOMBER COMMAND AIRCREW KILLED", "MORE THAN 55,000", "cnt-bc", 700) + `</g>`;
    return H.defs() + map + ham + crews + H.vignette(0.6) + H.grain();
  };

  // F23 — Warsaw, 1943 (straight)
  S["23"] = () => {
    // schematic Warsaw: the Vistula, the city, the walled ghetto (north-west of centre)
    const ghetto = "M560 300 L900 260 L980 420 L940 560 L1020 640 L880 720 L700 660 L600 560 L520 440Z";
    return H.defs() + `<rect width="1920" height="1080" fill="#1e2129"/>${Array.from({ length: 24 }, (_, i) => `<path d="M${i * 84} 0 L${i * 84 - 200} 1080" stroke="#262a33" stroke-width="4"/>`).join("")}${Array.from({ length: 14 }, (_, i) => `<path d="M0 ${i * 80} H1920" stroke="#262a33" stroke-width="4"/>`).join("")}` +
      `<path d="M1300 0 C1260 200 1380 380 1330 560 S1300 900 1380 1080 L1520 1080 C1440 900 1460 700 1480 560 S1420 200 1460 0Z" fill="#1c2c40" stroke="#5a6a80" stroke-width="4"/><text x="1500" y="900" class="t-map" font-size="34">VISTULA</text>` +
      `<text x="1080" y="880" text-anchor="middle" class="t-map" font-size="34">WARSAW</text>` +
      `<g id="fade-gfill"><path d="${ghetto}" fill="#4a4048" opacity=".9"/></g>` +
      `<g id="arr-wall"><path d="${ghetto}" stroke="#e9e2cf" stroke-width="10" fill="none" stroke-linejoin="round"/></g>` +
      `<g id="fade-glabel"><text x="760" y="490" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="40" fill="#e9e2cf">THE GHETTO</text></g>` +
      `<g id="smoke">${[[640, 420], [780, 360], [880, 520], [720, 600], [600, 520]].map(([x, y]) => H.smoke(x, y, 1.0)).join("")}<path d="${ghetto}" fill="#c84a1f" opacity=".45"/></g>` +
      `<g id="pop-d1">${sticker(420, 120, "19 APRIL 1943", { size: 48, rot: 0, bg: "#2a2c33" })}</g>` +
      `<g id="pop-d2"><g transform="translate(1400 160)"><rect x="-360" y="-60" width="720" height="120" rx="14" fill="#151820" stroke="#555" stroke-width="5"/><text y="16" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="42" fill="#fffaf0">19 APRIL → 16 MAY 1943</text></g></g>` +
      `<g id="pop-fighters" transform="translate(560 940)"><rect x="-420" y="-70" width="840" height="140" rx="16" fill="#151820" stroke="#555" stroke-width="5"/><text y="-12" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="30" fill="#c9c2b0">GHETTO FIGHTERS</text><text y="38" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="36" fill="#fffaf0">a few hundred · pistols · homemade bombs</text></g>` +
      `<g id="fade-candle" transform="translate(1640 700)"><rect x="-22" y="-80" width="44" height="120" rx="6" fill="#e9e2cf" stroke="#555" stroke-width="4"/><path d="M0 -84 C-16 -110 0 -140 0 -150 C8 -130 16 -110 0 -84Z" fill="#ffcf5a"/><text y="100" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="28" fill="#c9c2b0">REMEMBERED</text></g>` +
      H.vignette(0.6) + H.grain();
  };

  // F24 — The date: Tehran, Berlin, the cliffhanger, the end card
  S["24"] = () => {
    const tehran = H.room("#e2d2b0", "#8a6a48") + `<ellipse cx="960" cy="800" rx="520" ry="110" fill="#6b4a2c" stroke="${ink}" stroke-width="8"/><ellipse cx="960" cy="790" rx="480" ry="90" fill="#f4f1ea" stroke="${ink}" stroke-width="4"/>` +
      place(CAST.fdr({ pose: "hold" }), 520, 1060, 1.35, { id: "fdr" }) + place(CAST.stalin({ pose: "hold", prop: `<g transform="translate(150 214)"><rect x="-30" y="-40" width="60" height="80" fill="#fbf6e8" stroke="${ink}" stroke-width="4"/></g>` }), 960, 860, 1.25, { id: "stalin" }) + place(CAST.churchill({ pose: "hips" }), 1400, 1060, 1.35, { id: "church", flip: true }) +
      `<g id="pop-note" transform="translate(1600 330) rotate(4)"><rect x="-200" y="-110" width="400" height="220" fill="#fbf6e8" stroke="${ink}" stroke-width="6"/><text y="-50" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="28" fill="#555">STALIN'S NOTES</text><text y="30" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="56" fill="${K.red}">MAY 1944</text><path d="M-150 70 H150" stroke="${ink}" stroke-width="5"/></g>`;
    const dead = `<g id="fade-27" data-layout-allow-overlap="true"><rect width="1920" height="1080" fill="#1a1414"/>${H.map("east", { ussr: "#4a3434" }, { sea: "#0e131c", land: "#2a2e36" })}${H.counter(960, 540, "SOVIET CITIZENS WHO DIED IN THE WAR", "AROUND 27,000,000", "cnt-27", 820)}</g>`;
    const berlin = `<g id="cut-berlin" data-layout-allow-overlap="true">${H.room("#8a7d68", "#5a4e3c")}${place(CAST.hitler({ pose: "hips", mouth: "flat", brows: "angry" }), 560, 1040, 1.45, { id: "hitler" })}${place(CAST.klaus({ pose: "hold", brows: "sad" }), 1260, 1040, 1.4, { id: "klaus", flip: true })}<g id="gback">${P.gauge(1000, 820, 1.1, 0.0, { id: "" }).replace(">FUEL<", ">???<")}</g><g id="pop-no">${P.gauge(1000, 820, 1.6, 0.0, { label: "NO" })}</g>${sticker(1500, 160, "BERLIN", { size: 46, rot: 2, bg: ink })}</g>`;
    const W = "west";
    const where = `<g id="cut-where" data-layout-allow-overlap="true">${H.map(W, { uk: "#a08b5b", fr: AX, de: AX, benl: AX })}${H.arrow([[0.5, 51.4], [1.5, 51.1]], W, { id: "arr-cal", col: "#6f7766", w: 30 })}${(() => { const [x, y] = Geo.project([1.85, 50.95], W); return `<text x="${(x + 40).toFixed(0)}" y="${(y + 70).toFixed(0)}" class="t-map" font-size="40">CALAIS?</text>`; })()}<g id="st-wrong">${P.stamp(900, 520, 1.3, "WRONG", K.red, { rot: -10 })}</g><g id="pop-qn">${(() => { const [x, y] = Geo.project([-0.6, 49.4], W); return `<text x="${x.toFixed(0)}" y="${y.toFixed(0)}" text-anchor="middle" class="t-title" font-size="160" fill="#ffcc33">?</text>`; })()}</g>${sticker(400, 120, "WHERE WILL THEY LAND?", { size: 44, rot: -2, bg: ink })}</g>`;
    const endcard = `<g id="endcard" data-layout-allow-overlap="true"><rect x="-40" y="-40" width="2000" height="1160" fill="#14161c"/><text x="960" y="430" text-anchor="middle" font-family="Fredoka" font-weight="600" font-size="48" letter-spacing="8" fill="#c9c2b0">NEXT EPISODE</text><text x="960" y="560" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="104" fill="#fffaf0">The Year Hitler</text><text x="960" y="680" text-anchor="middle" font-family="Fredoka" font-weight="700" font-size="104" fill="#ffcc33">Lost Everything</text></g>`;
    return H.defs() + tehran + dead + berlin + where + endcard + H.date(300, 110, "TEHRAN, NOV 1943", "st-date") + H.grain();
  };

  g.WWH = H;
  g.Scenes = Object.assign(g.Scenes || {}, S);
})(globalThis);
